function alertMessages(value){if(Array.isArray(value))return value.flatMap(alertMessages);if(value&&typeof value==='object'){if(value.detail)return alertMessages(value.detail);if(value.msg){var loc=Array.isArray(value.loc)?value.loc.filter(function(x){return x!=='body'}).join(' › '):'';return[(loc?loc+'：':'')+value.msg]}return[JSON.stringify(value)]}var text=String(value||'未知错误').trim();if((text[0]==='['||text[0]==='{')){try{return alertMessages(JSON.parse(text))}catch(e){}}return text.split(/\r?\n|；|;\s+/).map(function(x){return x.trim()}).filter(Boolean)}
function alertSummary(text,max){text=String(text||'');return text.length>(max||88)?text.slice(0,(max||88)-1)+'…':text}
function alertPanelHtml(title,message,type){var items=alertMessages(message);if(!items.length)items=['未知错误'];var icon=type==='error'?'!':(type==='warning'?'△':'i');var content;if(items.length>1){content='<details class="compact-alert-more"><summary>查看全部 '+items.length+' 条信息</summary><ol>'+items.map(function(item){return '<li>'+esc(item)+'</li>'}).join('')+'</ol></details>'}else if(items[0].length>88){content='<details><summary>查看完整内容</summary><p class="compact-alert-full">'+esc(items[0])+'</p></details>'}else{content='<p>'+esc(items[0])+'</p>'}return '<div class="compact-alert '+esc(type||'info')+'"><span class="compact-alert-icon">'+icon+'</span><div class="compact-alert-body"><div class="compact-alert-title"><strong>'+esc(title)+'</strong>'+(items.length>1?'<em>'+items.length+' 条</em>':'')+'</div>'+content+'</div></div>'}
