function renderMd(text){if(!text)return '';var lines=String(text).split(/\r?\n/);var html=[],inTable=false,tableRows=[],listType=null,listItems=[];function inline(s){s=esc(s);s=s.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>');s=s.replace(/(?<!\w)\*(.+?)\*(?!\w)/g,'<em>$1</em>');s=s.replace(/`([^`]+)`/g,'<code>$1</code>');return s}function flushTable(){if(!inTable)return;if(tableRows.length){var th=tableRows[0].map(function(c){return '<th>'+inline(c)+'</th>'}).join('');var trs=tableRows.slice(1).map(function(r){return '<tr>'+r.map(function(c){return '<td>'+inline(c)+'</td>'}).join('')+'</tr>'}).join('');html.push('<table class="md-table"><thead><tr>'+th+'</tr></thead><tbody>'+trs+'</tbody></table>')}inTable=false;tableRows=[]}function flushList(){if(!listType)return;html.push('<'+listType+'>'+listItems.join('')+'</'+listType+'>');listType=null;listItems=[]}lines.forEach(function(line){var trimmed=line.trim();if(trimmed.indexOf('|')>=0&&trimmed.split('|').length>=3){flushList();inTable=true;var cells=trimmed.replace(/^\||\|$/g,'').split('|').map(function(c){return c.trim()});if(cells.length===1&&/^[-:\s]+$/.test(cells[0]))return;tableRows.push(cells);return}flushTable();if(!trimmed){flushList();html.push('<p></p>');return}var h=/^(#{1,4})\s+(.*)$/.exec(trimmed);if(h){flushList();html.push('<h'+h[1].length+'>'+inline(h[2])+'</h'+h[1].length+'>');return}if(/^[-*]\s+/.test(trimmed)){if(listType!=='ul'){flushList();listType='ul';listItems=[]}listItems.push('<li>'+inline(trimmed.replace(/^[-*]\s+/,''))+'</li>');return}if(/^\d+\.\s+/.test(trimmed)){if(listType!=='ol'){flushList();listType='ol';listItems=[]}listItems.push('<li>'+inline(trimmed.replace(/^\d+\.\s+/,''))+'</li>');return}flushList();html.push('<p>'+inline(trimmed)+'</p>')});flushTable();flushList();return html.join('')}
async function jsonRequest(url,body,method){var headers={'Content-Type':'application/json'};if(state.shareToken)headers['X-Share-Token']=state.shareToken;var response=await fetch(url,{method:method||'POST',headers:headers,body:JSON.stringify(body)});var data=await response.json();if(!response.ok)throw Error(alertMessages(data.detail||data).join('；'));return data}
