function loadDemoCase(){var today=new Date(),start=new Date(today.getTime()+86400000),end=new Date(today.getTime()+15*86400000);var iso=function(d){return d.toISOString().slice(0,10)};el('projectName').value='校园低碳生活倡议发布';el('background').value='面向全校同学策划一次低碳生活倡议活动，完成调研、内容策划、视觉物料、线上传播和效果复盘，最终形成可展示的活动方案与总结报告。';el('requirements').value='两周内完成；需要一份调研摘要、一套宣传图文、一场线下倡议活动和一份复盘报告。';el('startDate').value=iso(start);el('endDate').value=iso(end);el('members').innerHTML='';addMember({name:'林悦',skill_tags:['调研','数据分析','访谈','报告撰写']});addMember({name:'陈曦',skill_tags:['文案写作','报告撰写','活动策划']});addMember({name:'周航',skill_tags:['视觉设计','PPT','摄影','文案编辑']});state.files=[];state.fileAnalysis=null;state.fileMetadata=[];state.fileAnalysisKey='';el('files').value='';renderFileList();showNotice('演示案例已载入','success')}
