async function analyzeFiles(){if(!state.files.length)return;var key=state.input.background+'|'+state.files.map(function(f){return[f.name,f.size,f.lastModified].join(':')}).join('|');if(state.fileAnalysis&&state.fileAnalysisKey===key){state.input.uploaded_files=state.fileMetadata;state.input.requirement_analysis=state.fileAnalysis;renderFileList();return}var fd=new FormData();state.files.forEach(function(f){fd.append('files',f)});fd.append('background',state.input.background);var response=await fetch('/api/analyze-files',{method:'POST',body:fd});var data=await response.json();if(!response.ok)throw Error(data.detail||'文件分析失败');state.fileAnalysis=data.analysis;state.fileMetadata=(data.files||[]).concat(data.errors||[]);state.fileAnalysisKey=key;state.input.uploaded_files=state.fileMetadata;state.input.requirement_analysis=data.analysis;renderFileList()}
﻿﻿async function generateDraft(useAi,btn){var button=btn||el('generateBtn');var oldHtml=button.innerHTML;button.disabled=true;button.innerHTML='<span class="spinner-inline"></span>'+(useAi?'AI 生成中...':'快速生成中...');try{state.lastSavedFilename=null;state.planVersion=null;state.input=collectInput();if(!isLargeProject()&&!state.input.members.length)throw Error('请至少填写一名成员');if(!state.input.course.name)throw Error('请填写项目名称');if(!state.input.deadline)throw Error('请选择截止日期');if(state.files.length)await analyzeFiles();var data=await jsonRequest('/api/draft',{input:state.input,use_ai:useAi});state.draft=data.plan;if(isLargeProject())state.largeStage='modules';renderDraftView();setView('draft',1);resetChatMemory();var usedFallback=(data.warnings&&data.warnings.length)||data.plan.summary.indexOf('AI 拆解本次未成功')===0;showNotice(usedFallback?'AI 本次未返回可用草案，已改用确定性兜底蓝图（可重新生成或手动编辑）':'任务草案已生成',usedFallback?'info':'success')}catch(error){showNotice(error.message,'error')}finally{button.disabled=false;button.innerHTML=oldHtml}}
function renderDraftView(){if(isLargeProject()){if(state.largeStage==='modules')renderLargeModules();else if(state.largeStage==='backbones')renderLargeBackbones();else renderLargeTasks()}else{renderSmallDraft()}}
function updateDraftFooter(){var btn=el('confirmDraftBtn'),hint=el('draftHint');if(isLargeProject()){if(state.largeStage==='modules'){btn.textContent='下一步：骨干认领';hint.textContent='编辑模块后进入骨干认领'}else if(state.largeStage==='backbones'){btn.textContent='下一步：子任务拆解';hint.textContent='为每个模块认领骨干后继续'}else{btn.textContent='确认拆解并开始分工';hint.textContent=''}}else{btn.textContent='确认拆解并开始分工';hint.textContent=''}}
function renderSmallDraft(){el('draftToolbar').innerHTML='<div class="toolbar-title"><h2>任务拆解</h2><p>编辑任务后确认开始分工</p></div><div class="toolbar-actions"><button class="btn btn-ghost" id="addTaskBtn">＋ 新增任务</button><button class="btn btn-ghost" id="mergeTaskBtn">合并选中</button><button class="btn btn-ghost" id="redraftBtn">重新生成</button></div>';el('draftSummary').innerHTML='<strong>'+esc(state.draft.summary)+'</strong><p>'+esc(state.draft.reasoning||'任务已按专业能力、交付流程和依赖关系拆解。')+'</p>';var tasks=state.draft.tasks.slice().sort(function(a,b){return a.order-b.order});el('taskEditor').innerHTML=tasks.map(renderTaskCard).join('');updateDraftFooter();var total=tasks.reduce(function(s,t){return s+t.estimated_hours},0);el('draftTotal').textContent=tasks.length+' 项任务 · '+total.toFixed(1)+' 小时';el('addTaskBtn').onclick=function(){mutateDraft([{op:'add'}]).catch(function(e){showNotice(e.message,'error')})};el('mergeTaskBtn').onclick=mergeSelectedTasks;el('redraftBtn').onclick=function(){generateDraft(true,el('redraftBtn'))};bindTaskCards()}
function renderTaskCard(task){var estimateHint=task.estimate_reason?'<small class="estimate-hint" title="'+esc(task.estimate_reason)+'">参考 '+task.estimate_min_hours+'-'+task.estimate_max_hours+'h</small>':'';var memberOpts=(state.input.members||[]).map(function(m){return '<option '+(m.name===task.assignee_id?'selected':'')+'>'+esc(m.name)+'</option>'}).join('');var moduleOpts=((state.draft&&state.draft.modules)||[]).length?((state.draft&&state.draft.modules)||[]).map(function(m){return '<option value="'+esc(m.id)+'" '+(m.id===task.module_id?'selected':'')+'>'+esc(m.name)+'</option>'}).join(''):'';return '<article class="task-edit-card" data-id="'+esc(task.id)+'"><div class="task-edit-top"><input type="checkbox" class="task-select"><span class="drag-handle" draggable="true" title="拖动排序">⋮⋮</span><span class="task-code">'+esc(task.id)+'</span><input class="task-name-input" value="'+esc(task.name)+'"><button class="split-task btn-small" type="button">拆分</button><button class="remove-task icon-danger" type="button">×</button></div><textarea class="task-description" rows="2">'+esc(task.description)+'</textarea><div class="task-fields"><label>预计工时<input class="task-hours-input" type="number" min=".5" step=".5" value="'+task.estimated_hours+'">'+estimateHint+'</label><label>建议人数<input class="task-people" type="number" min="1" max="10" value="'+(task.suggested_people||1)+'"></label><label>执行阶段<select class="task-stage">'+['准备','执行','收尾','自定义'].map(function(s){return '<option '+(s===task.execution_stage?'selected':'')+'>'+s+'</option>'}).join('')+'</select></label><label>自定义阶段<input class="task-custom-stage" value="'+esc(task.custom_stage||'')+'"></label><label>开始日期<input class="task-start" type="date" value="'+(task.start_date?String(task.start_date).slice(0,10):'')+'"></label><label>截止日期<input class="task-end" type="date" value="'+(task.end_date?String(task.end_date).slice(0,10):'')+'"></label><label>所需技能<input class="task-skills" value="'+esc((task.required_skills||[]).join(','))+'"></label><label>负责人<select class="task-assignee"><option value="">未分配</option>'+memberOpts+'</select></label>'+(moduleOpts?'<label>所属模块<select class="task-module">'+moduleOpts+'</select></label>':'')+(isLargeProject()?'<label>需招募<input class="task-volunteers" type="number" min="0" max="20" value="'+(task.extra_helpers_needed||0)+'"></label>':'')+'<label>依赖任务<input class="task-dependencies" value="'+esc((task.dependencies||[]).join(','))+'"></label></div></article>'}
function taskFromCard(card){var old=state.draft.tasks.find(function(t){return t.id===card.dataset.id});if(!old)return null;var startVal=card.querySelector('.task-start').value||null;var endVal=card.querySelector('.task-end').value||null;var oldStart=old.start_date?String(old.start_date).slice(0,10):null;var oldEnd=old.end_date?String(old.end_date).slice(0,10):null;var datesManual=(startVal!==oldStart)||(endVal!==oldEnd)||!!old.dates_manual;return Object.assign({},old,{name:card.querySelector('.task-name-input').value.trim(),description:card.querySelector('.task-description').value.trim(),estimated_hours:+card.querySelector('.task-hours-input').value,suggested_people:+card.querySelector('.task-people').value||1,execution_stage:card.querySelector('.task-stage').value,custom_stage:card.querySelector('.task-custom-stage').value.trim()||null,start_date:startVal,end_date:endVal,dates_manual:datesManual,required_skills:splitTags(card.querySelector('.task-skills').value),dependencies:splitTags(card.querySelector('.task-dependencies').value),module_id:card.querySelector('.task-module')?(card.querySelector('.task-module').value||null):old.module_id,extra_helpers_needed:card.querySelector('.task-volunteers')?(+card.querySelector('.task-volunteers').value||0):(old.extra_helpers_needed||0),assignee_id:card.querySelector('.task-assignee')?(card.querySelector('.task-assignee').value||null):old.assignee_id})}
function collectDraftTasks(){return Array.from(document.querySelectorAll('.task-edit-card')).map(taskFromCard).filter(Boolean)}
function bindTaskCards(){document.querySelectorAll('.task-edit-card').forEach(function(card){card.querySelector('.remove-task').onclick=function(){mutateDraft([{op:'remove',task_id:card.dataset.id}]).catch(function(e){showNotice(e.message,'error')})};card.querySelector('.split-task').onclick=function(){syncDraftTasks().then(function(){return mutateDraft([{op:'split',task_id:card.dataset.id}])}).catch(function(e){showNotice(e.message,'error')})};var handle=card.querySelector('.drag-handle');handle.ondragstart=function(e){card.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/task-id',card.dataset.id)};handle.ondragend=function(){card.classList.remove('dragging')};card.ondragover=function(e){e.preventDefault();e.dataTransfer.dropEffect='move'};card.ondrop=function(e){e.preventDefault();var src=e.dataTransfer.getData('text/task-id');var ids=state.draft.tasks.slice().sort(function(a,b){return a.order-b.order}).map(function(t){return t.id});var from=ids.indexOf(src),to=ids.indexOf(card.dataset.id);if(from<0||to<0||from===to)return;ids.splice(to,0,ids.splice(from,1)[0]);mutateDraft([{op:'reorder',ordered_ids:ids}]).catch(function(e){showNotice(e.message,'error')})}})}
async function syncDraftTasks(){var tasks=collectDraftTasks();for(var i=0;i<tasks.length;i++){if(tasks[i].execution_stage==='自定义'&&!tasks[i].custom_stage)throw new Error('任务 '+tasks[i].id+' 选了自定��阶段，请填写名称')}var ops=tasks.map(function(t){return{op:'update',task_id:t.id,task:t}});if(ops.length)state.draft=await jsonRequest('/api/draft/mutate',{plan:state.draft,operations:ops});return state.draft}
async function mutateDraft(operations){state.draft=await jsonRequest('/api/draft/mutate',{plan:state.draft,operations:operations});renderDraftView()}
function mergeSelectedTasks(){var ids=Array.from(document.querySelectorAll('.task-select:checked')).map(function(cb){return cb.closest('.task-edit-card').dataset.id});if(ids.length<2){showNotice('请至少选中两项任务','info');return}mutateDraft([{op:'merge',task_ids:ids}]).catch(function(e){showNotice(e.message,'error')})}
﻿﻿function renderLargeModules(){el('draftToolbar').innerHTML='<div class="toolbar-title"><h2>大模块拆解</h2><p>编辑模块名称与描述，可拖拽排序、合并或新增</p></div><div class="toolbar-actions"><button class="btn btn-ghost" id="addModuleBtn">＋ 新增模块</button><button class="btn btn-ghost" id="mergeModuleBtn">合并选中模块</button><button class="btn btn-ghost" id="redraftModuleBtn">重新生成</button></div>';el('draftSummary').innerHTML='<strong>'+esc(state.draft.summary)+'</strong><p>大型项目先拆成大模块，每个模块后续由骨干认领，再拆子任务。拖动模块卡片左侧手柄可调整顺序。</p>';var modules=(state.draft.modules||[]).slice().sort(function(a,b){return(a.order||0)-(b.order||0)});if(!modules.length){el('taskEditor').innerHTML='<p class="module-empty-hint">暂无模块，点击新增模块开始拆分。</p>'}else{el('taskEditor').innerHTML=modules.map(function(m){var modTasks=state.draft.tasks.filter(function(t){return t.module_id===m.id});return '<div class="module-edit-card" data-module-id="'+esc(m.id)+'"><div class="module-edit-head"><input type="checkbox" class="module-select"><span class="module-drag-handle" draggable="true" title="拖动排序">⋮⋮</span><span class="module-code">'+esc(m.id)+'</span><input class="module-name-input" value="'+esc(m.name)+'" placeholder="模块名称"><span class="module-count-chip">'+modTasks.length+' 项子任务</span><button class="remove-module icon-danger" type="button">×</button></div><textarea class="module-desc-input" rows="2" placeholder="模块目标与交付边界">'+esc(m.description||'')+'</textarea>'+(modTasks.length?'<div class="module-task-preview">'+modTasks.slice(0,5).map(function(t){return '<span class="module-task-chip">'+esc(t.name)+' ('+t.estimated_hours+'h)</span>'}).join('')+(modTasks.length>5?'<span class="module-task-chip">+'+(modTasks.length-5)+' 项</span>':'')+'</div>':'')+'</div>'}).join('')}updateDraftFooter();var totalHours=state.draft.tasks.reduce(function(s,t){return s+t.estimated_hours},0);el('draftTotal').textContent=modules.length+' 个大模块 · '+state.draft.tasks.length+' 项子任务 · '+totalHours.toFixed(1)+'h';el('draftHint').textContent=modules.length<2?'建议至少拆出 2 个模块':'';el('addModuleBtn').onclick=function(){mutateDraft([{op:'add_module'}]).catch(function(e){showNotice(e.message,'error')})};el('mergeModuleBtn').onclick=mergeSelectedModules;if(el('redraftModuleBtn'))el('redraftModuleBtn').onclick=function(){generateDraft(true,el('redraftModuleBtn'))};bindModuleCards()}function bindModuleCards(){document.querySelectorAll('.module-edit-card').forEach(function(card){var removeBtn=card.querySelector('.remove-module');if(removeBtn){removeBtn.onclick=function(){var modTasks=state.draft.tasks.filter(function(t){return t.module_id===card.dataset.moduleId});if(modTasks.length){showNotice('请先在子任务拆解阶段移走该模块下的任务','info');return}if(!confirm('确定删除模块 '+card.dataset.moduleId+'？'))return;mutateDraft([{op:'remove_module',module_id:card.dataset.moduleId}]).catch(function(e){showNotice(e.message,'error')})}}var handle=card.querySelector('.module-drag-handle');if(handle){handle.ondragstart=function(e){card.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/module-id',card.dataset.moduleId)};handle.ondragend=function(){card.classList.remove('dragging')};card.ondragover=function(e){e.preventDefault();e.dataTransfer.dropEffect='move'};card.ondrop=function(e){e.preventDefault();var src=e.dataTransfer.getData('text/module-id');if(!src||src===card.dataset.moduleId)return;var ids=(state.draft.modules||[]).slice().sort(function(a,b){return(a.order||0)-(b.order||0)}).map(function(m){return m.id});var from=ids.indexOf(src),to=ids.indexOf(card.dataset.moduleId);if(from<0||to<0||from===to)return;ids.splice(to,0,ids.splice(from,1)[0]);syncModules().then(function(){return mutateDraft([{op:'reorder_modules',ordered_module_ids:ids}])}).catch(function(e){showNotice(e.message,'error')})}}})}function mergeSelectedModules(){var ids=Array.from(document.querySelectorAll('.module-select:checked')).map(function(cb){return cb.closest('.module-edit-card').dataset.moduleId});if(ids.length<2){showNotice('请至少选中两个模块','info');return}mutateDraft([{op:'merge_modules',module_ids:ids}]).catch(function(e){showNotice(e.message,'error')})}
async function syncModules(){var ops=[];document.querySelectorAll('.module-edit-card').forEach(function(card){var moduleId=card.dataset.moduleId;var original=(state.draft.modules||[]).find(function(m){return m.id===moduleId});if(!original)return;var newName=card.querySelector('.module-name-input').value.trim();var newDesc=card.querySelector('.module-desc-input').value.trim();if(newName!==original.name||newDesc!==(original.description||'')){ops.push({op:'update_module',module_id:moduleId,module:Object.assign({},original,{name:newName,description:newDesc})})}});if(ops.length)state.draft=await jsonRequest('/api/draft/mutate',{plan:state.draft,operations:ops});return state.draft}
function renderLargeBackbones(){el('draftToolbar').innerHTML='<div class="toolbar-title"><h2>骨干认领</h2><p>添加骨干成员，再为每个模块指定负责人</p></div><div class="toolbar-actions"></div>';var modules=(state.draft.modules||[]).slice().sort(function(a,b){return(a.order||0)-(b.order||0)});var members=state.input.members||[];var memberNames=members.filter(function(m){return m.name}).map(function(m){return m.name});var claimed=modules.filter(function(m){return m.assignee_id}).length;el('draftSummary').innerHTML='<strong>'+memberNames.length+' 名骨干 · 已认领 '+claimed+' / '+modules.length+' 个模块</strong><p>先在下方添加骨干成员，再为每个模块选择负责人。骨干认领后，其下子任务默认归属该骨干。</p>';var panel='<div class="draft-member-panel"><div class="draft-member-head"><div><h3>骨干管理</h3><p>添加项目骨干，每个骨干可认领一个大模块</p></div><button class="text-btn" id="addBackboneBtn" type="button">＋ 添加骨干</button></div><div class="draft-member-list" id="backboneList">'+members.map(function(m,i){return '<div class="draft-member-row" data-idx="'+i+'"><input class="bb-name" value="'+esc(m.name||'')+'" placeholder="骨干姓名"><select class="bb-role">'+roleOptionsHtml(m.role||'骨干 / 模块负责人')+'</select><input class="bb-manager" placeholder="上级姓名" value="'+esc(m.manager||'')+'"><input class="bb-skills" value="'+esc((m.skill_tags||[]).join(','))+'" placeholder="技能标签，逗号分隔"><div class="hours-input"><input class="bb-hours" type="number" min=".5" step=".5" value="'+(m.daily_available_hours||4)+'"><span>h/天</span></div><button class="icon-danger remove-bb" type="button">×</button></div>'}).join('')+'</div></div>';var cards=modules.map(function(m){var taskCount=state.draft.tasks.filter(function(t){return t.module_id===m.id}).length;return '<div class="module-claim-card" data-module-id="'+esc(m.id)+'"><div class="module-claim-title"><span class="module-code">'+esc(m.id)+'</span><div><strong>'+esc(m.name)+'</strong>'+(m.description?'<span>'+esc(m.description)+'</span>':'')+'</div></div><div class="module-claim-meta">'+taskCount+' 项子任务</div><label>骨干<select class="module-owner-select" data-module-owner="'+esc(m.id)+'"><option value="">未认领</option>'+memberNames.map(function(name){return '<option '+(name===m.assignee_id?'selected':'')+'>'+esc(name)+'</option>'}).join('')+'</select></label></div>'}).join('');el('taskEditor').innerHTML=panel+cards;document.querySelectorAll('.bb-role').forEach(bindRoleSelect);updateDraftFooter();el('draftTotal').textContent=memberNames.length+' 名骨干 · '+claimed+' / '+modules.length+' 已认领';el('draftHint').textContent=memberNames.length===0?'请先添加骨干成员':(claimed<modules.length?'尚有模块未认领':'');el('addBackboneBtn').onclick=function(){if(!state.input.members)state.input.members=[];state.input.members.push({name:'',role:'骨干 / 模块负责人',manager:'',skill_tags:[],daily_available_hours:4});renderLargeBackbones()};document.querySelectorAll('.remove-bb').forEach(function(btn){btn.onclick=function(){var row=btn.closest('.draft-member-row');var idx=+row.dataset.idx;var removedName=state.input.members[idx]?state.input.members[idx].name:'';state.input.members.splice(idx,1);if(removedName){(state.draft.modules||[]).forEach(function(m){if(m.assignee_id===removedName)m.assignee_id=null})}renderLargeBackbones()}});document.querySelectorAll('.bb-name').forEach(function(inp){inp.addEventListener('blur',function(){var rows=document.querySelectorAll('.draft-member-row');rows.forEach(function(row,idx){if(state.input.members[idx]){state.input.members[idx].name=row.querySelector('.bb-name').value.trim()}});state.input.members=state.input.members.filter(function(m){return m.name});var names=state.input.members.map(function(m){return m.name});document.querySelectorAll('[data-module-owner]').forEach(function(sel){var current=sel.value;var html='<option value="">未认领</option>';names.forEach(function(n){html+='<option value="'+esc(n)+'" '+(n===current?'selected':'')+'>'+esc(n)+'</option>'});sel.innerHTML=html})})});document.querySelectorAll('[data-module-owner]').forEach(function(sel){sel.onchange=function(){var moduleId=sel.dataset.moduleOwner;var module=(state.draft.modules||[]).find(function(m){return m.id===moduleId});if(module)module.assignee_id=sel.value||null;renderLargeBackbones()}})}async function syncBackbones(){if(document.querySelector('#backboneList')){var collected=[];document.querySelectorAll('.draft-member-row').forEach(function(row){var name=row.querySelector('.bb-name')?row.querySelector('.bb-name').value.trim():'';if(!name)return;var skills=row.querySelector('.bb-skills')?splitTags(row.querySelector('.bb-skills').value):[];var hours=row.querySelector('.bb-hours')?+row.querySelector('.bb-hours').value||4:4;collected.push({name:name,role:row.querySelector('.bb-role')?row.querySelector('.bb-role').value.trim()||'骨干':'骨干',manager:row.querySelector('.bb-manager')?row.querySelector('.bb-manager').value.trim():'',skill_tags:skills,daily_available_hours:hours,available_hours:hours*14,profile_mode:'tags',bio:''})});state.input.members=collected}var ops=[];document.querySelectorAll('[data-module-owner]').forEach(function(sel){var moduleId=sel.dataset.moduleOwner;var original=(state.draft.modules||[]).find(function(m){return m.id===moduleId});if(!original)return;if((original.assignee_id||'')!==sel.value){ops.push({op:'update_module',module_id:moduleId,module:Object.assign({},original,{assignee_id:sel.value||null})})}});if(ops.length)state.draft=await jsonRequest('/api/draft/mutate',{plan:state.draft,operations:ops});return state.draft}function renderLargeTasks(){el('draftToolbar').innerHTML='<div class="toolbar-title"><h2>子任务拆解</h2><p>编辑各模块下的子任务</p></div><div class="toolbar-actions"><button class="btn btn-ghost" id="addTaskBtn">＋ 新增任务</button><button class="btn btn-ghost" id="mergeTaskBtn">合并选中</button><button class="btn btn-ghost" id="redraftBtn">重新生成</button></div>';el('draftSummary').innerHTML='<strong>'+esc(state.draft.summary)+'</strong><p>编辑各模块下的子任务。</p>';var modules=(state.draft.modules||[]).slice().sort(function(a,b){return(a.order||0)-(b.order||0)});el('taskEditor').innerHTML=modules.map(function(m){var tasks=state.draft.tasks.filter(function(t){return t.module_id===m.id}).sort(function(a,b){return(a.order||0)-(b.order||0)});return '<div class="module-edit-card"><div class="module-edit-head"><span class="module-code">'+esc(m.id)+'</span><strong style="font-size:14px">'+esc(m.name)+'</strong><span class="module-count-chip">'+tasks.length+' 项</span><button class="btn-small add-task-to-module" data-module="'+esc(m.id)+'">＋ 添加子任务</button></div><div class="module-task-list">'+tasks.map(renderTaskCard).join('')+'</div></div>'}).join('');updateDraftFooter();var total=state.draft.tasks.reduce(function(s,t){return s+t.estimated_hours},0);el('draftTotal').textContent=state.draft.tasks.length+' 项子任务 · '+total.toFixed(1)+'h';el('addTaskBtn').onclick=function(){var firstMod=(state.draft.modules||[])[0];mutateDraft([{op:'add',module_id:firstMod?firstMod.id:''}]).catch(function(e){showNotice(e.message,'error')})};el('mergeTaskBtn').onclick=mergeSelectedTasks;if(el('redraftBtn'))el('redraftBtn').onclick=function(){generateDraft(true,el('redraftBtn'))};document.querySelectorAll('.add-task-to-module').forEach(function(btn){btn.onclick=function(){mutateDraft([{op:'add',module_id:btn.dataset.module}]).catch(function(e){showNotice(e.message,'error')})}});bindTaskCards()}
async function syncCurrentStage(){if(!isLargeProject())return syncDraftTasks();if(state.largeStage==='modules')return syncModules();if(state.largeStage==='backbones')return syncBackbones();return syncDraftTasks()}
async function onConfirmDraft(){var btn=el('confirmDraftBtn');var oldText=btn.textContent;btn.disabled=true;btn.innerHTML='<span class="spinner-inline"></span>处理中…';try{if(isLargeProject()&&state.largeStage==='modules'){await syncModules();state.largeStage='backbones';renderDraftView();state.activeStep=2;renderSteps()}else if(isLargeProject()&&state.largeStage==='backbones'){await syncBackbones();state.largeStage='tasks';renderDraftView();state.activeStep=3;renderSteps()}else{await syncDraftTasks();var data=await jsonRequest('/api/confirm-draft',{input:state.input,plan:state.draft});state.plan=data;state.automatic=JSON.parse(JSON.stringify(data));['saveBtn','exportMdBtn','exportDocxBtn','exportPdfBtn','exportExcelBtn','exportCsvBtn','exportIcsBtn','shareBtn'].forEach(function(b){el(b).disabled=false});renderBoard();setView('board',isLargeProject()?4:2);rebuildBaselineKeepHistory();showNotice('自动分工已完成，可拖拽调整','success')}}catch(error){showNotice(error.message,'error')}finally{btn.disabled=false;updateDraftFooter()}}
﻿﻿function renderBoardToolbar(){var toolbar=el('boardToolbar');if(isLargeProject()){el('largeBoardTabs').classList.remove('hidden');el('largeBoardTabs').innerHTML='<button class="large-board-tab '+(state.largeBoardTab==='modules'?'active':'')+'" data-board-tab="modules">模块分工</button><button class="large-board-tab '+(state.largeBoardTab==='volunteers'?'active':'')+'" data-board-tab="volunteers">志愿者招募</button>';el('largeBoardTabs').querySelectorAll('.large-board-tab').forEach(function(btn){btn.onclick=function(){state.largeBoardTab=btn.dataset.boardTab;renderBoard()}});toolbar.innerHTML='<div class="toolbar-title"><h2>'+(state.largeBoardTab==='modules'?'模块分工':'志愿者招募')+'</h2></div>'}else{el('largeBoardTabs').classList.add('hidden');toolbar.innerHTML='<div class="toolbar-title"><h2>智能分工</h2><p>拖拽任务卡或下拉选择负责人</p></div><div class="toolbar-actions"><button class="btn btn-ghost" id="resetAssignBtn">恢复自动分工</button></div>';if(el('resetAssignBtn'))el('resetAssignBtn').onclick=resetAssignment}}
function renderBoard(){renderBoardToolbar();if(isLargeProject()&&state.largeBoardTab==='volunteers'){el('workloadSummary').innerHTML='';el('balanceWarnings').innerHTML='';renderVolunteerRecruit();return}var names=state.plan.input.members.map(function(m){return m.name});if(isLargeProject())renderLargeBoard(names);else renderSmallBoard(names);refreshWorkload().catch(function(e){showNotice(e.message,'error')})}
function renderSmallBoard(names){var groups={},assistGroups={};names.concat(['未分配']).forEach(function(n){groups[n]=[];assistGroups[n]=[]});state.plan.plan.tasks.forEach(function(task){var owner=task.assignee_id||'未分配';if(groups[owner])groups[owner].push(task);var qa=(state.plan.qa_matrix&&state.plan.qa_matrix.assignments||[]).find(function(a){return a.task_id===task.id});var collabs=[];if(qa){if(qa.qa_primary&&qa.qa_primary!==owner)collabs.push(qa.qa_primary);(qa.qa_support||[]).forEach(function(s){if(s&&s!==owner&&collabs.indexOf(s)<0)collabs.push(s)})}else{(task.collaborator_ids||[]).forEach(function(c){if(c!==owner)collabs.push(c)})}if(qa){if(qa.qa_primary&&qa.qa_primary!==owner&&assistGroups[qa.qa_primary])assistGroups[qa.qa_primary].push({task:task,type:'primary'});(qa.qa_support||[]).forEach(function(s){if(s&&s!==owner&&assistGroups[s])assistGroups[s].push({task:task,type:'support'})})}else{collabs.forEach(function(cn){if(assistGroups[cn])assistGroups[cn].push({task:task,type:'support'})})}});el('board').className='assignment-board';el('board').innerHTML=Object.keys(groups).map(function(owner){var hours=groups[owner].reduce(function(s,t){return s+t.estimated_hours},0);var assistH=assistGroups[owner].reduce(function(s,item){return s+item.task.estimated_hours*(item.type==='primary'?0.3:0.15)},0);var meta=groups[owner].length+' 项'+(assistGroups[owner].length?' · 协助'+assistGroups[owner].length:'')+' · '+(hours+assistH).toFixed(1)+'h';return '<section class="member-column" data-owner="'+esc(owner)+'"><header><div class="avatar">'+esc(owner.slice(0,1))+'</div><div><strong>'+esc(owner)+'</strong><span>'+meta+'</span></div></header><div class="member-task-list">'+groups[owner].map(function(task){return renderAssignmentCard(task,names)}).join('')+assistGroups[owner].map(function(item){return '<article class="assignment-card assist-card"><div class="assignment-title"><strong>'+esc(item.task.name)+'</strong><span>'+(item.type==='primary'?'主要协助':'协助')+'</span></div><div class="assignment-meta">'+esc(item.task.execution_stage)+'</div></article>'}).join('')+'</div></section>'}).join('');bindBoard(names)}
function renderAssignmentCard(task,names){return '<article class="assignment-card" draggable="true" data-task="'+esc(task.id)+'"><div class="assignment-title"><strong>'+esc(task.name)+'</strong><span>'+task.estimated_hours+'h</span></div><div class="assignment-meta">'+esc(task.execution_stage)+' · '+esc((task.required_skills||[]).join(' / ')||'通用')+'</div><label>负责人<select class="owner-select"><option value="">未分配</option>'+names.map(function(n){return '<option value="'+esc(n)+'" '+(n===task.assignee_id?'selected':'')+'>'+esc(n)+'</option>'}).join('')+'</select></label><button type="button" class="collaborator-btn">协作者：'+esc((task.collaborator_ids||[]).join('、')||'无')+'</button></article>'}
function bindBoard(names){document.querySelectorAll('.assignment-card:not(.assist-card)').forEach(function(card){card.ondragstart=function(e){e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/task-id',card.dataset.task)};var ownerSel=card.querySelector('.owner-select');if(ownerSel){ownerSel.onchange=function(){var task=state.plan.plan.tasks.find(function(t){return t.id===card.dataset.task});var old=task.assignee_id||'未分配';task.assignee_id=this.value||null;task.collaborator_ids=(task.collaborator_ids||[]).filter(function(n){return n!==task.assignee_id});recordDelta('任务 '+task.id+' 负责人：'+old+'→'+(task.assignee_id||'未分配'));renderBoard()}}var collabBtn=card.querySelector('.collaborator-btn');if(collabBtn){collabBtn.onclick=function(){var task=state.plan.plan.tasks.find(function(t){return t.id===card.dataset.task});var value=prompt('输入协作者姓名，用逗号分隔：',(task.collaborator_ids||[]).join(','));if(value===null)return;task.collaborator_ids=splitTags(value).filter(function(n){return names.indexOf(n)>=0&&n!==task.assignee_id});recordDelta('任务 '+task.id+' 协作者：'+(task.collaborator_ids.join(',')||'无'));renderBoard()}}});document.querySelectorAll('.member-column').forEach(function(column){column.ondragover=function(e){e.preventDefault();e.dataTransfer.dropEffect='move';column.classList.add('drag-over')};column.ondragleave=function(){column.classList.remove('drag-over')};column.ondrop=function(e){e.preventDefault();column.classList.remove('drag-over');var task=state.plan.plan.tasks.find(function(t){return t.id===e.dataTransfer.getData('text/task-id')});if(!task)return;var old=task.assignee_id||'未分配';task.assignee_id=column.dataset.owner==='未分配'?null:column.dataset.owner;task.collaborator_ids=(task.collaborator_ids||[]).filter(function(n){return n!==task.assignee_id});recordDelta('任务 '+task.id+' 负责人：'+old+'→'+(task.assignee_id||'未分配'));renderBoard()}})}
function renderLargeBoard(names){var modules=(state.plan.plan.modules||[]).slice().sort(function(a,b){return(a.order||0)-(b.order||0)});el('board').className='assignment-board board-large';el('board').innerHTML=modules.map(function(m){var tasks=state.plan.plan.tasks.filter(function(t){return t.module_id===m.id});return '<div class="board-module" data-module-id="'+esc(m.id)+'"><div class="board-module-head"><div class="board-module-title"><span class="module-code">'+esc(m.id)+'</span><div><strong>'+esc(m.name)+'</strong><span>'+tasks.length+' 项子任务</span></div></div><label>骨干<select class="module-owner-select" data-module-owner="'+esc(m.id)+'"><option value="">未认领</option>'+names.map(function(n){return '<option '+(n===m.assignee_id?'selected':'')+'>'+esc(n)+'</option>'}).join('')+'</select></label></div><div class="board-module-tasks">'+tasks.map(function(task){return renderAssignmentCard(task,names)}).join('')+'</div></div>'}).join('');document.querySelectorAll('[data-module-owner]').forEach(function(sel){sel.onchange=function(){var moduleId=sel.dataset.moduleOwner;var original=(state.plan.plan.modules||[]).find(function(m){return m.id===moduleId});if(!original)return;var oldOwner=original.assignee_id||'';original.assignee_id=sel.value||null;var newOwner=original.assignee_id||'';state.plan.plan.tasks.forEach(function(task){if(task.module_id===moduleId){if(!task.assignee_id&&newOwner){task.assignee_id=newOwner;task.collaborator_ids=(task.collaborator_ids||[]).filter(function(n){return n!==newOwner})}else if(task.assignee_id===oldOwner&&oldOwner&&!newOwner){task.assignee_id=null}}});recordDelta('模块 '+moduleId+' 骨干：'+(oldOwner||'未认领')+'→'+(newOwner||'未认领'));renderBoard()}});bindBoard(names)}
function resetAssignment(){if(!state.automatic)return;state.plan=JSON.parse(JSON.stringify(state.automatic));renderBoard();showNotice('已恢复自动分工','info')}
async function refreshWorkload(){var snapshot=await jsonRequest('/api/workload',state.plan);var members=snapshot.members;var cards=Object.keys(members).map(function(name){var item=members[name];var cnt=item.task_count+(item.assist_count?' +协助'+item.assist_count:'');return '<div class="workload-card"><div><strong>'+esc(name)+'</strong><span>'+cnt+' · '+item.total_hours+'h</span></div><div class="load-track"><i style="width:'+Math.min(100,item.share*100)+'%"></i></div><small>'+esc(item.role||'执行成员')+' · '+Math.round(item.share*100)+'% 团队工作量</small></div>'}).join('');var vols=(snapshot.volunteers||[]).map(function(v){return '<div class="workload-card volunteer-load-card"><div><strong>'+esc(v.name)+'</strong><span>'+(v.task_count||0)+' 项 · '+v.total_hours+'h</span></div><div class="load-track"><i style="width:'+Math.min(100,v.share*100)+'%"></i></div><small>志愿者 / 外部协作者 · '+Math.round(v.share*100)+'% 总人力</small></div>'}).join('');el('workloadSummary').innerHTML=cards+vols;el('balanceWarnings').innerHTML=snapshot.warnings.length?alertPanelHtml('分工建议',snapshot.warnings,'warning'):'<div class="success-box">当前技能匹配和工作量较为均衡</div>'}
﻿﻿function renderVolunteerRecruit(){var modules=(state.plan.plan.modules||[]).slice().sort(function(a,b){return(a.order||0)-(b.order||0)});var recruitTasks=state.plan.plan.tasks.filter(function(t){return(t.extra_helpers_needed||0)>0});el('board').className='assignment-board board-large';if(!recruitTasks.length){el('board').innerHTML='<div class="success-box">当前没有需要招募志愿者的任务。</div>';return}var byModule={};recruitTasks.forEach(function(t){var mid=t.module_id||'_none';if(!byModule[mid])byModule[mid]=[];byModule[mid].push(t)});el('board').innerHTML='<div class="volunteer-recruit"><div class="volunteer-recruit-head"><h3>志愿者招募</h3><p>为需要额外人手的任务招募外部志愿者。</p></div>'+modules.filter(function(m){return byModule[m.id]}).map(function(m){return '<div class="volunteer-module-section" data-module-id="'+esc(m.id)+'"><header><strong>'+esc(m.name)+'</strong><span>需招募 '+byModule[m.id].length+' 项</span></header>'+byModule[m.id].map(function(task){return renderVolunteerTask(task)}).join('')+'</div>'}).join('')+'</div>';bindVolunteerControls()}
function renderVolunteerTask(task){var pool=state.plan.volunteer_pool||[];var taskVols=pool.filter(function(v){return v.task_id===task.id});var need=task.extra_helpers_needed||0;var active=taskVols.filter(function(v){return v.status!=='已婉拒'}).length;var full=active>=need;var rows=taskVols.map(function(v,idx){return '<div class="volunteer-row" data-volunteer-idx="'+idx+'" data-task-id="'+esc(task.id)+'"><input class="volunteer-name" value="'+esc(v.name)+'" placeholder="姓名"><input class="volunteer-contact" value="'+esc(v.contact||'')+'" placeholder="联系方式"><select class="volunteer-status">'+['待确认','已确认','已婉拒'].map(function(s){return '<option '+(s===v.status?'selected':'')+'>'+s+'</option>'}).join('')+'</select><input class="volunteer-note" value="'+esc(v.note||'')+'" placeholder="备注"><button class="volunteer-remove" type="button">×</button></div>'}).join('');return '<div class="volunteer-task" data-task-id="'+esc(task.id)+'"><header><strong>'+esc(task.name)+'</strong><span>需 '+need+' 人 · 已认领 '+active+'</span></header><div class="volunteer-list">'+(rows||'<div class="volunteer-empty">暂无认领</div>')+'</div>'+(full?'<div class="volunteer-full">已满员（'+active+'/'+need+'）</div>':'<div class="volunteer-add"><input class="volunteer-add-name" placeholder="志愿者姓名"><input class="volunteer-add-contact" placeholder="联系方式（可选）"><button class="volunteer-add-btn" type="button" data-task-id="'+esc(task.id)+'">＋ 添加</button></div>')+'</div>'}
function bindVolunteerControls(){document.querySelectorAll('.volunteer-remove').forEach(function(btn){btn.onclick=function(){var row=btn.closest('.volunteer-row');var taskId=row.dataset.taskId,idx=+row.dataset.volunteerIdx;var pool=state.plan.volunteer_pool||[];var taskPool=pool.filter(function(v){return v.task_id===taskId});if(taskPool[idx]){pool.splice(pool.indexOf(taskPool[idx]),1);saveVolunteers(pool)}}});document.querySelectorAll('.volunteer-add-btn').forEach(function(btn){btn.onclick=async function(){var taskId=btn.dataset.taskId;var section=btn.closest('.volunteer-task');var name=section.querySelector('.volunteer-add-name').value.trim();var contact=section.querySelector('.volunteer-add-contact').value.trim();if(!name){showNotice('请填写志愿者姓名','info');return}var pool=(state.plan.volunteer_pool||[]).slice();pool.push({name:name,task_id:taskId,status:'待确认',contact:contact,note:''});btn.disabled=true;try{await saveVolunteers(pool);showNotice('已添加志愿者 '+name,'success')}finally{btn.disabled=false}}});document.querySelectorAll('.volunteer-row input, .volunteer-row select').forEach(function(field){field.onchange=debouncedSaveVolunteers})}
function debouncedSaveVolunteers(){if(volunteerSaveTimer)clearTimeout(volunteerSaveTimer);volunteerSaveTimer=setTimeout(function(){volunteerSaveTimer=null;saveVolunteers()},600)}async function saveVolunteers(explicitPool){if(volunteerSaveTimer){clearTimeout(volunteerSaveTimer);volunteerSaveTimer=null}var ae=document.activeElement;var fTask=ae&&ae.closest&&ae.closest('[data-task-id]')?ae.closest('[data-task-id]').dataset.taskId:'';var fIdx=ae&&ae.closest&&ae.closest('[data-volunteer-idx]')?ae.closest('[data-volunteer-idx]').dataset.volunteerIdx:'';var fCls=ae?ae.className:'';var fPos=ae&&'selectionStart'in ae?ae.selectionStart:null;var pool=explicitPool||[];if(!explicitPool){document.querySelectorAll('.volunteer-task').forEach(function(taskSection){var taskId=taskSection.dataset.taskId;taskSection.querySelectorAll('.volunteer-row').forEach(function(row){pool.push({name:row.querySelector('.volunteer-name').value.trim(),task_id:taskId,status:row.querySelector('.volunteer-status').value,contact:row.querySelector('.volunteer-contact').value.trim(),note:row.querySelector('.volunteer-note').value.trim()})})})}try{state.plan=await jsonRequest('/api/volunteers',{plan:state.plan,volunteers:pool});renderVolunteerRecruit();if(fTask&&fCls){var fSel='[data-task-id="'+fTask+'"]';if(fIdx)fSel+=' [data-volunteer-idx="'+fIdx+'"]';fSel+=' .'+fCls.split(' ')[0];var target=document.querySelector(fSel);if(target){target.focus();try{if(fPos!=null&&'setSelectionRange'in target&&target.value.length>=fPos)target.setSelectionRange(fPos,fPos)}catch(e){}}}}catch(e){showNotice(e.message,'error');throw e}}
async function onConfirmAssignment(){var btn=el('confirmAssignmentBtn');var oldText=btn.textContent;btn.disabled=true;btn.innerHTML='<span class="spinner-inline"></span>保存中…';try{var assignees={},collaborators={},moduleAssignees={};state.plan.plan.tasks.forEach(function(task){assignees[task.id]=task.assignee_id||'';collaborators[task.id]=task.collaborator_ids||[]});if(isLargeProject()){document.querySelectorAll('[data-module-owner]').forEach(function(sel){moduleAssignees[sel.dataset.moduleOwner]=sel.value})}state.plan=await jsonRequest('/api/manual-assignment',{plan:state.plan,assignees:assignees,collaborators:collaborators,module_assignees:moduleAssignees});renderFinal();setView('final',isLargeProject()?5:3);rebuildBaselineKeepHistory();showNotice('最终分工已确认','success')}catch(error){showNotice(error.message,'error')}finally{btn.disabled=false;btn.textContent=oldText}}
function audienceTabs(role,defenseVisible){
  if(role==='member')return[{id:'mine',label:'我的任务'},{id:'schedule',label:'团队排期'},{id:'collaboration',label:'协作关系'}];
  if(role==='reviewer')return[{id:'evaluation',label:'方案评审'},{id:'report',label:'项目报告'}].concat(defenseVisible?[{id:'interview',label:'答辩模拟'}]:[]);
  return[{id:'tasks',label:'任务计划'},{id:'schedule',label:'排期资源'},{id:'team',label:'团队负载'},{id:'collaboration',label:'分工协作'},{id:'review',label:'执行复盘'},{id:'report',label:'项目报告'}].concat(defenseVisible?[{id:'interview',label:'答辩模拟'}]:[]);
}
function audienceDefaultTab(role){return role==='member'?'mine':(role==='reviewer'?'evaluation':'tasks')}
function renderAudienceControls(){
  var role=state.audienceRole||'manager';
  var members=(state.plan&&state.plan.input&&state.plan.input.members)||[];
  if(!state.audienceMember||!members.some(function(m){return m.name===state.audienceMember}))state.audienceMember=members.length?members[0].name:'';
  document.querySelectorAll('[data-audience-role]').forEach(function(button){
    button.classList.toggle('active',button.dataset.audienceRole===role);
    button.onclick=function(){if(state.audienceRole===button.dataset.audienceRole)return;state.audienceRole=button.dataset.audienceRole;state.resultTab=audienceDefaultTab(state.audienceRole);renderFinal()};
  });
  var picker=el('audienceMemberPicker');
  if(picker){
    picker.innerHTML='';
    members.forEach(function(member){var option=document.createElement('option');option.value=member.name;option.textContent=member.name;option.selected=member.name===state.audienceMember;picker.appendChild(option)});
    picker.classList.toggle('hidden',role!=='member');
    picker.disabled=!members.length;
    picker.onchange=function(){state.audienceMember=picker.value;renderFinal()};
  }
  var defenseVisible=shouldShowDefense();
  var tabs=audienceTabs(role,defenseVisible);
  var tabBar=el('resultTabs');
  tabBar.innerHTML='';
  tabs.forEach(function(tab){var button=document.createElement('button');button.dataset.tab=tab.id;button.textContent=tab.label;tabBar.appendChild(button)});
  if(!tabs.some(function(tab){return tab.id===state.resultTab}))state.resultTab=audienceDefaultTab(role);
  renderAudienceSummary();
}
function audiencePlanStats(){
  var tasks=(state.plan&&state.plan.plan&&state.plan.plan.tasks)||[];
  var assignments=(state.plan&&state.plan.qa_matrix&&state.plan.qa_matrix.assignments)||[];
  var assigned=tasks.filter(function(task){return!!task.assignee_id}).length;
  var blocked=tasks.filter(function(task){return task.status==='blocked'}).length;
  var active=tasks.filter(function(task){return task.status==='in_progress'}).length;
  var completed=tasks.filter(function(task){return task.status==='completed'}).length;
  var totalHours=tasks.reduce(function(sum,task){return sum+(+task.estimated_hours||0)},0);
  var averageMatch=assignments.length?Math.round(assignments.reduce(function(sum,item){return sum+(+item.score||0)},0)/assignments.length*100):0;
  return{tasks:tasks,taskCount:tasks.length,assigned:assigned,blocked:blocked,active:active,completed:completed,totalHours:Math.round(totalHours*10)/10,averageMatch:averageMatch,critical:((state.plan.timeline&&state.plan.timeline.critical_path)||[]).length};
}
function renderAudienceSummary(){
  var target=el('audienceSummary');if(!target)return;
  var role=state.audienceRole||'manager';var stats=audiencePlanStats();
  var project=state.plan.input&&state.plan.input.course?state.plan.input.course.name:'未命名项目';
  var deadline=state.plan.input&&state.plan.input.deadline?String(state.plan.input.deadline).slice(0,10):'未设置';
  var title=role==='member'?(state.audienceMember?state.audienceMember+'的执行视图':'成员执行视图'):(role==='reviewer'?'教师 / 评委视图':'负责人总览');
  var description=role==='member'?'聚焦个人负责和协作任务，同时保留团队排期上下文。':(role==='reviewer'?'基于计划数据查看范围、分工覆盖、排期证据和风险，不改变执行状态。':'掌握全局进度、团队负载和当前阻塞，及时调整计划。');
  var chips=role==='reviewer'
    ? '<span><strong>'+stats.taskCount+'</strong>项任务</span><span><strong>'+stats.totalHours+'h</strong>总工时</span><span><strong>'+stats.assigned+'/'+stats.taskCount+'</strong>已分工</span><span><strong>'+stats.critical+'</strong>项关键路径</span>'
    : '<span><strong>'+stats.completed+'/'+stats.taskCount+'</strong>已完成</span><span><strong>'+stats.active+'</strong>进行中</span><span class="'+(stats.blocked?'is-risk':'')+'"><strong>'+stats.blocked+'</strong>阻塞</span><span><strong>'+esc(deadline)+'</strong>截止</span>';
  target.innerHTML='<div><span class="audience-kicker">'+esc(project)+'</span><h2>'+esc(title)+'</h2><p>'+esc(description)+'</p></div><div class="audience-metrics">'+chips+'</div>';
}
function renderMemberTasks(){
  var name=state.audienceMember;var tasks=audiencePlanStats().tasks.filter(function(task){return task.assignee_id===name||(task.collaborator_ids||[]).indexOf(name)>=0});
  if(!name)return'<div class="success-box">当前方案还没有可选择的成员。</div>';
  if(!tasks.length)return'<div class="success-box">'+esc(name)+' 当前没有负责或协作任务。</div>';
  return'<div class="member-focus-head"><strong>'+esc(name)+' · '+tasks.length+' 项相关任务</strong><span>负责人任务与协作任务已合并展示</span></div><div class="final-grid">'+tasks.map(renderFinalTaskCard).join('')+'</div>';
}
function renderEvaluationView(){
  var stats=audiencePlanStats();var deadline=state.plan.input&&state.plan.input.deadline?String(state.plan.input.deadline).slice(0,10):'未设置';
  var coverage=stats.taskCount?Math.round(stats.assigned/stats.taskCount*100):0;
  var risks=[];if(stats.blocked)risks.push(stats.blocked+' 项任务处于阻塞状态');if(stats.assigned<stats.taskCount)risks.push((stats.taskCount-stats.assigned)+' 项任务尚未明确负责人');if(!stats.critical)risks.push('当前排期未识别出关键路径');
  var reportRisk=state.plan.report&&state.plan.report.risk_note?state.plan.report.risk_note.trim():'';if(reportRisk)risks.push(reportRisk);
  var riskHtml=risks.length?'<ul>'+risks.map(function(risk){return'<li>'+esc(risk)+'</li>'}).join('')+'</ul>':'<div class="success-box">当前结构化计划未发现阻塞或未分工事项。</div>';
  return'<div class="evaluation-grid"><article><span>交付边界</span><strong>'+stats.taskCount+' 项任务 · '+stats.totalHours+'h</strong><small>截止 '+esc(deadline)+'</small></article><article><span>分工完整度</span><strong>'+coverage+'%</strong><small>'+stats.assigned+'/'+stats.taskCount+' 项已明确负责人</small></article><article><span>平均匹配度</span><strong>'+stats.averageMatch+'%</strong><small>来自分工矩阵的技能匹配证据</small></article><article><span>排期证据</span><strong>'+stats.critical+' 项关键任务</strong><small>可在项目报告中查看完整依据</small></article></div>'+resultSection('风险与待核验项','仅呈现计划中可追溯的数据，不生成主观评分。','<div class="evaluation-risks">'+riskHtml+'</div>');
}
﻿﻿function renderFinal(){renderAudienceControls();renderResultTab(state.resultTab)}
function statusOptions(current){return[['pending','待开始'],['in_progress','进行中'],['completed','已完成'],['blocked','阻塞']].map(function(item){return '<option value="'+item[0]+'" '+(item[0]===current?'selected':'')+'>'+item[1]+'</option>'}).join('')}
function renderReviewContent(){var tasks=state.plan.plan.tasks||[];var statusLabels={pending:'待开始',in_progress:'进行中',completed:'已完成',blocked:'阻塞'};var planned=0,actual=0,completed=0,withActual=0;tasks.forEach(function(t){planned+=t.estimated_hours||0;if(t.actual_hours!=null){actual+=t.actual_hours}if(t.status==='completed')completed++;if(t.actual_hours!=null)withActual++});var rows=tasks.map(function(task){var a=task.actual_hours;var dev=a!=null?Math.round((a-task.estimated_hours)*10)/10:null;var devPct=a!=null?Math.round((a-task.estimated_hours)/Math.max(0.1,task.estimated_hours)*100):null;var cls=dev==null?'':(dev>0.5?'review-over':dev<-0.5?'review-under':'review-ok');var actualText=a!=null?(a+'h'):(task.status==='completed'?'待填写':'—');var devText=dev==null?'—':(dev>0?'+'+dev+'h':dev+'h')+(devPct!=null?'（'+devPct+'%）':'');return '<tr class="'+cls+'"><td>'+esc(task.id)+'</td><td>'+esc(task.name)+'</td><td>'+esc(task.assignee_id||'未分配')+'</td><td>'+(task.estimated_hours||0)+'h</td><td>'+actualText+'</td><td>'+devText+'</td><td>'+esc(statusLabels[task.status]||task.status)+'</td></tr>'}).join('');var summary='<div class="review-summary"><div><strong>'+Math.round(planned*10)/10+'h</strong><span>计划总工时</span></div><div><strong>'+Math.round(actual*10)/10+'h</strong><span>已记录实际工时</span></div><div><strong>'+completed+' / '+tasks.length+'</strong><span>已完成任务</span></div><div><strong>'+withActual+'</strong><span>已填写复盘</span></div></div>';return summary+'<div class="review-table-wrap"><table><thead><tr><th>编号</th><th>任务</th><th>负责人</th><th>计划工时</th><th>实际工时</th><th>偏差</th><th>状态</th></tr></thead><tbody>'+rows+'</tbody></table></div>'}function renderGantt(){var tasks=state.plan.timeline.tasks||[];if(!tasks.length)return '<div class="success-box">暂无时间线数据</div>';var dates=tasks.flatMap(function(t){return[new Date(t.start_date),new Date(t.end_date)]});var min=new Date(Math.min.apply(null,dates)),max=new Date(Math.max.apply(null,dates));var span=Math.max(1,(max-min)/86400000+1);var statusLabels={pending:'待开始',in_progress:'进行中',completed:'已完成',blocked:'阻塞'};var legend='<div class="gantt-legend"><span><i class="legend-critical"></i>关键路径</span><span><i class="legend-urgent"></i>紧急</span><span><i class="legend-normal"></i>浮动充足</span><span><i class="legend-blocked"></i>阻塞</span></div>';var head='<div class="gantt-row gantt-row-head"><span>任务</span><div class="gantt-track-label">时间轴</div><div class="gantt-meta">日期 / 工期 / 浮动</div></div>';var rows=tasks.map(function(task){var start=(new Date(task.start_date)-min)/86400000;var width=Math.max(1,(new Date(task.end_date)-new Date(task.start_date))/86400000+1);var left=start/span*100,w=width/span*100;var cls=task.status==='blocked'?'blocked':task.is_critical?'critical':(task.float_days!==undefined&&task.float_days<=1?'urgent':'normal');var floatLabel=task.is_critical?'关键路径':(task.float_days!==undefined?'浮动 '+task.float_days+'d':'');var statusLabel=statusLabels[task.status]||'';var meta=[floatLabel,statusLabel].filter(Boolean).join(' · ');var rowCls=task.status==='completed'?'is-completed':(task.status==='blocked'?'is-blocked':'');return '<div class="gantt-row '+rowCls+'"><span title="'+esc(task.name)+'">'+esc(task.name)+'</span><div class="gantt-track"><i class="'+cls+'" style="left:'+left+'%;width:'+Math.max(2,w)+'%"></i></div><div class="gantt-meta"><strong>'+esc(String(task.start_date).slice(0,10))+' → '+esc(String(task.end_date).slice(0,10))+'</strong><small>'+Math.round(width)+' 天'+(meta?' · '+meta:'')+'</small></div></div>'}).join('');return '<div class="gantt-head"><strong>项目甘特图</strong><span>总工期 '+state.plan.timeline.total_days+' 工作日</span></div>'+legend+'<div class="gantt-chart">'+head+rows+'</div>'}function refreshModuleOwnerLabels(){var roles={};document.querySelectorAll('#backboneList .draft-member-row').forEach(function(row){var name=row.querySelector('.bb-name')?row.querySelector('.bb-name').value.trim():'';var role=row.querySelector('.bb-role')?row.querySelector('.bb-role').value:'';if(name)roles[name]=role});document.querySelectorAll('[data-module-owner] option').forEach(function(option){if(!option.value)return;option.textContent=option.value+(isVolunteerRole(roles[option.value])?'（志愿者）':'')})}
