renderLargeBackbones=function(){renderLargeBackbonesWithoutDates();document.querySelectorAll('#backboneList .draft-member-row').forEach(function(row,index){var member=(state.input.members||[])[index]||{};var remove=row.querySelector('.remove-bb');var holder=document.createElement('div');holder.innerHTML=unavailablePickerHtml(member.unavailable_dates||[],'bb-unavailable');var picker=holder.firstElementChild;row.insertBefore(picker,remove);bindUnavailablePicker(picker);var role=row.querySelector('.bb-role');if(role)role.addEventListener('change',function(){setTimeout(function(){applyBackboneRowVisibility(row);refreshModuleOwnerLabels()},0)});applyBackboneRowVisibility(row)});var toolbar=el('draftToolbar');if(toolbar){var p=toolbar.querySelector('p');if(p)p.textContent='骨干与志愿者都可以认领模块'}var head=document.querySelector('.draft-member-head');if(head){var h=head.querySelector('h3');var hp=head.querySelector('p');if(h)h.textContent='认领成员';if(hp)hp.textContent='骨干可填写完整档案；志愿者只需姓名和身份'}var add=el('addBackboneBtn');if(add)add.textContent='＋ 添加认领成员';refreshModuleOwnerLabels()};
