syncBackbones=async function(){var datesByName={};document.querySelectorAll('#backboneList .draft-member-row').forEach(function(row){applyBackboneRowVisibility(row);var name=row.querySelector('.bb-name')?row.querySelector('.bb-name').value.trim():'';var role=row.querySelector('.bb-role')?row.querySelector('.bb-role').value:'';if(name)datesByName[name]=isVolunteerRole(role)?[]:unavailableDatesFrom(row,'bb-unavailable')});var result=await syncBackbonesWithoutDates();(state.input.members||[]).forEach(function(member){member.manager=isVolunteerRole(member.role)?'':member.manager;member.skill_tags=isVolunteerRole(member.role)?[]:member.skill_tags;member.unavailable_dates=datesByName[member.name]||normalizeUnavailableDates(member.unavailable_dates||[])});return result};
