function analysisToText(a){if(typeof a==='string')return a;if(!a||typeof a!=='object')return '';var lines=[];if(a.summary)lines.push(a.summary);if(a.project_goal)lines.push('项目目标：'+a.project_goal);if(Array.isArray(a.core_tasks)&&a.core_tasks.length)lines.push('核心任务：'+a.core_tasks.join('、'));if(Array.isArray(a.deliverables)&&a.deliverables.length)lines.push('交付物：'+a.deliverables.join('、'));if(Array.isArray(a.task_requirements)&&a.task_requirements.length)lines.push('任务要求：'+a.task_requirements.join('、'));return lines.join('\n')}function appendDefenseInput(text){var ta=el('defenseScript');if(!ta)return;var cur=ta.value||'';ta.value=cur?cur+'\n\n'+text:text;ivChat.script=ta.value;ta.focus()}async function defenseVoiceDone(blob){var btn=el('defenseVoiceBtn');if(btn)btn.disabled=true;showNotice('正在理解语音需求…','info');try{var fd=new FormData();fd.append('file',blob,'voice.webm');var r=await fetch('/api/realtime/voice-requirement',{method:'POST',body:fd});var data=await r.json();if(!r.ok)throw Error(alertMessages(data.detail||data).join('；'));var text=(data.text||'').trim();if(!text)throw Error('未能理解语音内容');appendDefenseInput('[语音需求] '+text);showNotice('语音需求已加入答辩稿','success')}catch(e){showNotice('语音需求失败：'+e.message,'error')}finally{if(btn)btn.disabled=false}}async function defensePhotoSelected(){var input=el('defensePhotoInput');var file=input&&input.files&&input.files[0];if(input)input.value='';if(!file)return;defensePhotoFile(file)}async function defensePhotoFile(file){if(!file)return;showNotice('正在理解图片需求…','info');try{var fd=new FormData();fd.append('files',file);fd.append('background','');var r=await fetch('/api/analyze-files',{method:'POST',body:fd});var data=await r.json();if(!r.ok)throw Error(alertMessages(data.detail||data).join('；'));var analysis=analysisToText(data.analysis);if(!analysis)throw Error('未能理解图片内容');appendDefenseInput('[图片需求] '+analysis);showNotice('图片需求已加入答辩稿','success')}catch(e){showNotice('图片需求失败：'+e.message,'error')}}function renderDefensePanel(){var fileNames=ivChat.files.map(function(file){return file.name});var files=fileNames.length?fileNames.map(function(name){return '<span>'+esc(name)+'</span>'}).join(''):'<small>支持 PPTX、PDF、Word、TXT、Markdown，单个不超过 15MB</small>';return '<div class="interview-panel defense-panel"><div class="interview-head"><h3>答辩模拟</h3><p>根据实际答辩要求和你提交的答辩稿或 PPT 模拟现场提问，不检查任务完成状态。</p></div><div class="defense-materials"><div class="interview-req"><label>答辩稿</label><textarea id="defenseScript" rows="6" placeholder="可以直接粘贴答辩稿、讲稿提纲或逐页讲解内容…">'+esc(ivChat.script||'')+'</textarea><div class="defense-voice-photo"><button type="button" id="defenseVoiceBtn" class="btn btn-ghost" title="说出你的答辩需求，AI 理解成要点后加入答辩稿">🎤 语音输入需求</button><button type="button" id="defensePhotoBtn" class="btn btn-ghost" title="拍摄白板/需求截图，AI 理解后加入答辩稿">📷 拍照需求</button><input id="defensePhotoInput" type="file" hidden accept="image/*" capture="environment"></div><div class="defense-input-hint">💡 AI 会自动理解语音/拍照需求并加入答辩稿，自动参与评委提问设计；如需修正可直接编辑答辩稿。</div></div><div class="defense-upload"><input id="defenseFiles" class="hidden" type="file" multiple accept=".pptx,.pdf,.docx,.txt,.md"><button id="defenseChooseBtn" type="button" class="btn btn-ghost">上传 PPT / 答辩稿</button><div id="defenseFileList" class="defense-file-list">'+files+'</div></div></div><div class="interview-req"><label>评委关注点（可选）</label><textarea id="interviewRequirements" rows="2" placeholder="例如：重点追问数据来源和创新点">'+esc(ivChat.requirements||'')+'</textarea></div><div class="interview-actions"><button id="startInterviewBtn" class="btn btn-primary">开始答辩模拟</button><button id="resetInterviewBtn" class="btn btn-ghost">重新开始</button></div><div id="interviewMessages" class="interview-messages"><div class="interview-placeholder">提交答辩稿或 PPT 后，AI 评委会围绕材料逐题提问。</div></div><form id="interviewForm" class="interview-form hidden"><div class="interview-input"><textarea id="interviewAnswer" rows="2" placeholder="输入你的现场回答…"></textarea><div class="interview-mode-toggle"><button type="button" class="active" data-interview-mode="answer">回答问题</button><button type="button" data-interview-mode="adjust">调整提问</button></div></div><button type="submit" id="interviewSubmitBtn">发送</button></form></div>'}
function renderResultTab(tab){
  var defenseVisible=shouldShowDefense();
  var validTabs=audienceTabs(state.audienceRole||'manager',defenseVisible).map(function(item){return item.id});
  if(validTabs.indexOf(tab)<0)tab='tasks';
  state.resultTab=tab;
  document.querySelectorAll('#resultTabs button').forEach(function(button){button.classList.toggle('active',button.dataset.tab===tab)});
  var tasks=state.plan.plan.tasks||[];
  var completed=tasks.filter(function(t){return t.status==='completed'}).length;
  var percent=Math.round(completed/Math.max(1,tasks.length)*100);
  var content='';
  if(tab==='mine')content=renderMemberTasks();
  if(tab==='evaluation')content=renderEvaluationView();
  if(tab==='tasks'){
    content='<div class="progress-card"><div><strong>项目进度</strong><span>'+completed+'/'+tasks.length+'（'+percent+'%）</span></div><div class="progress-track"><i style="width:'+percent+'%"></i></div></div>';
    if(isLargeProject()&&(state.plan.plan.modules||[]).length){
      content+=state.plan.plan.modules.slice().sort(function(a,b){return(a.order||0)-(b.order||0)}).map(function(m){var moduleTasks=tasks.filter(function(t){return t.module_id===m.id});return '<div class="final-module"><div class="final-module-head"><span class="module-code">'+esc(m.id)+'</span><div><strong>'+esc(m.name)+'</strong><span>骨干：'+esc(m.assignee_id||'未认领')+' · '+moduleTasks.length+' 项子任务</span></div></div><div class="final-grid">'+moduleTasks.map(renderFinalTaskCard).join('')+'</div></div>'}).join('');
    }else{content+='<div class="final-grid">'+tasks.map(renderFinalTaskCard).join('')+'</div>'}
  }
  if(tab==='schedule')content='<div class="result-section-stack">'+resultSection('项目排期','查看任务先后关系、关键路径与整体工期。',renderGantt())+resultSection('资源日历','在同一排期下检查成员每日负载与资源冲突。','<div id="resourceCalendarContent"><p class="muted-loading">正在生成资源日历…</p></div>')+'</div>';
  if(tab==='team')content='<div class="result-section-stack">'+(isLargeProject()?resultSection('组织关系','确认大型项目的骨干、志愿者和负责人关系。',renderOrgContent()):'')+resultSection('工作量分布','检查成员任务量、协作量和阶段负载。','<div id="workloadDetail" class="workload-detail"><p class="muted-loading">加载中…</p></div>')+'</div>';
  if(tab==='collaboration')content=state.audienceRole==='member'?'<div class="result-section-stack">'+resultSection('我的协作关系','仅展示当前成员负责、答疑或支持的任务。',renderAssignmentMatrix(state.audienceMember))+'</div>':'<div class="result-section-stack">'+resultSection('分工矩阵','集中查看负责人、协作者与匹配度。',renderAssignmentMatrix())+resultSection('任务参与清单','维护每项任务的实际参与者和贡献工时。',renderParticipantsContent())+(state.readOnly?'':resultSection('成员管理','成员变化后统一重算分工与排期。',renderMemberEditor()))+'</div>';
  if(tab==='review')content='<div class="result-section-stack">'+resultSection('任务复盘','对比计划与实际工时，定位执行偏差。',renderReviewContent())+resultSection('执行提醒','汇总逾期、临期和阻塞事项。','<div id="remindersContent"><p class="muted-loading">正在生成提醒…</p></div>')+resultSection('组织复盘','按成员和角色复盘投入产出。','<div id="orgReviewContent"><p class="muted-loading">正在生成组织复盘…</p></div>')+'</div>';
  if(tab==='report')content='<div class="report-box"><p class="muted-loading">正在生成完整报告…</p></div>';
  if(tab==='interview')content=renderDefensePanel();
  el('resultContent').innerHTML=content;
  if(tab==='tasks'||tab==='mine')bindStatusControls();
  if(tab==='schedule')loadResourceCalendarTab('resourceCalendarContent');
  if(tab==='team'){bindOrgContent();renderWorkloadTab()}
  if(tab==='collaboration'&&state.audienceRole!=='member'){bindParticipantsControls();if(!state.readOnly)bindMemberEditControls()}
  if(tab==='review'){loadRemindersTab();loadOrgReviewTab()}
  if(tab==='report')loadReportTab();
  if(tab==='interview')bindInterviewControls();
}
function renderFinalTaskCard(task){return '<article class="final-card status-'+task.status+'"><div><span class="task-code">'+esc(task.id)+'</span><strong>'+esc(task.name)+'</strong></div><p>'+esc(task.description)+'</p><footer><span>'+esc(task.assignee_id||'未分配')+'</span><span>'+task.estimated_hours+'h</span><span>建议'+(task.suggested_people||1)+'人</span>'+(task.extra_helpers_needed?'<span class="volunteer-chip">需招'+task.extra_helpers_needed+'人</span>':'')+'<select class="status-select" data-task-status="'+esc(task.id)+'">'+statusOptions(task.status)+'</select>'+(task.status==='completed'?'<div class="actual-inputs"><label>实际工时<input class="actual-hours-input" data-task-id="'+esc(task.id)+'" type="number" min="0" step="0.5" value="'+(task.actual_hours!=null?task.actual_hours:'')+'" placeholder="计划 '+task.estimated_hours+'h"></label><label>完成日期<input class="actual-date-input" data-task-id="'+esc(task.id)+'" type="date" value="'+(task.actual_end_date?String(task.actual_end_date).slice(0,10):'')+'"></label></div>':'')+'</footer></article>'}function bindActualInputs(){document.querySelectorAll('.actual-hours-input,.actual-date-input').forEach(function(inp){inp.onchange=async function(){var taskId=inp.dataset.taskId;var task=state.plan.plan.tasks.find(function(t){return t.id===taskId});if(!task)return;var hoursInput=document.querySelector('.actual-hours-input[data-task-id="'+taskId+'"]');var dateInput=document.querySelector('.actual-date-input[data-task-id="'+taskId+'"]');var actualHours=hoursInput&&hoursInput.value!==''?+hoursInput.value:null;var actualDate=dateInput&&dateInput.value?dateInput.value:null;try{state.plan=await jsonRequest('/api/task-actual',{plan:state.plan,task_id:taskId,actual_hours:actualHours,actual_end_date:actualDate});renderResultTab(state.resultTab);showNotice('实际工时已记录','success')}catch(e){showNotice(e.message,'error')}}})}function bindStatusControls(){document.querySelectorAll('[data-task-status]').forEach(function(sel){sel.onchange=async function(){var taskId=sel.dataset.taskStatus;var task=state.plan.plan.tasks.find(function(t){return t.id===taskId});if(task)task.status=sel.value;try{state.plan=await jsonRequest('/api/recompute',state.plan);renderResultTab(state.resultTab);showNotice('状态已更新','success')}catch(e){showNotice(e.message,'error')}}}) ;bindActualInputs()}async function renderWorkloadTab(){var target=el('workloadDetail');if(!target)return;target.innerHTML='<div class="workload-loading"><span class="spinner-inline"></span>正在计算团队负载…</div>';try{var snapshot=await jsonRequest('/api/workload',state.plan);var members=Object.keys(snapshot.members||{}).map(function(name){var item=snapshot.members[name];var cnt=item.task_count+(item.assist_count?' +协助'+item.assist_count:'');return '<article><div><strong>'+esc(name)+'</strong><span>'+esc(item.role||'执行成员')+' · '+cnt+' · '+item.total_hours+'h · '+Math.round(item.share*100)+'%</span></div><div class="load-track"><i style="width:'+Math.min(100,item.share*100)+'%"></i></div><p>'+Object.keys(item.stage_hours||{}).map(function(stage){return esc(stage)+' '+item.stage_hours[stage]+'h'}).join(' · ')+'</p></article>'}).join('');var volunteers=(snapshot.volunteers||[]).map(function(v){return '<article class="volunteer-load-card"><div><strong>'+esc(v.name)+'</strong><span>志愿者 / 外部协作者 · '+(v.task_count||0)+' 项 · '+v.total_hours+'h · '+Math.round(v.share*100)+'%</span></div><div class="load-track"><i style="width:'+Math.min(100,v.share*100)+'%"></i></div><p>'+Object.keys(v.stage_hours||{}).map(function(stage){return esc(stage)+' '+v.stage_hours[stage]+'h'}).join(' · ')+'</p></article>'}).join('');target.innerHTML=members+volunteers||'<div class="success-box">暂无可统计的成员负载</div>'}catch(error){target.innerHTML=alertPanelHtml('团队负载加载失败',error.message,'error')+'<button type="button" id="retryWorkloadBtn" class="btn btn-ghost workload-retry">重新加载</button>';var retry=el('retryWorkloadBtn');if(retry)retry.onclick=renderWorkloadTab}}
﻿﻿async function ensureGeneratedReport(){if(!state.plan)throw Error('暂无可生成报告的方案');var report=state.plan.report||{};if((report.summary||'').trim()||(report.timeline_section||'').trim()||(report.qa_matrix_section||'').trim())return state.plan;var r=await fetch('/api/report',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(state.plan)});var data=await r.json();if(!r.ok)throw Error(data.detail||'报告生成失败');state.plan=data;return data}
async function loadReportTab(){var target=el('resultContent');if(!target)return;target.innerHTML='<div class="report-box"><span class="spinner-inline"></span>正在生成报告…</div>';try{await ensureGeneratedReport();var r=await fetch('/api/export/markdown',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(state.plan)});if(!r.ok)throw Error('报告生成失败');var text=await r.text();target.innerHTML='<div class="report-box">'+renderMd(text)+'</div>'}catch(e){target.innerHTML='<div class="report-box">'+alertPanelHtml('报告生成失败',e.message,'error')+'</div>'}}
function renderDefenseFileList(){var target=el('defenseFileList');if(!target)return;target.innerHTML=ivChat.files.length?ivChat.files.map(function(file){return '<span>'+esc(file.name)+'</span>'}).join(''):'<small>支持 PPTX、PDF、Word、TXT、Markdown，单个不超过 15MB</small>'}
function bindInterviewControls(){ensureInterviewVoiceControls();var startBtn=el('startInterviewBtn'),resetBtn=el('resetInterviewBtn');var form=el('interviewForm'),input=el('interviewAnswer'),script=el('defenseScript'),requirements=el('interviewRequirements'),files=el('defenseFiles'),choose=el('defenseChooseBtn');if(startBtn)startBtn.onclick=startInterviewChat;if(resetBtn)resetBtn.onclick=function(){resetInterviewChat();showNotice('已重新开始','info')};if(form)form.onsubmit=sendInterviewAnswer;if(input)input.disabled=!ivChat.started;if(script)script.oninput=function(){ivChat.script=script.value};var dVoice=el('defenseVoiceBtn'),dPhoto=el('defensePhotoBtn'),dPhotoIn=el('defensePhotoInput');if(dVoice)dVoice.onclick=function(e){if(e)e.stopPropagation();toggleRecording(defenseVoiceDone,'defense')};if(dPhoto)dPhoto.onclick=function(e){if(e)e.stopPropagation();openCamera('defense')};if(dPhotoIn)dPhotoIn.onchange=defensePhotoSelected;if(requirements)requirements.oninput=function(){ivChat.requirements=requirements.value};if(choose&&files)choose.onclick=function(){files.click()};if(files)files.onchange=function(){ivChat.files=mergeFiles(ivChat.files,Array.from(files.files||[]),4);files.value='';ivChat.materialText='';ivChat.materialNames=[];resetInterviewChat();renderDefenseFileList()};document.querySelectorAll('.interview-mode-toggle button').forEach(function(btn){btn.onclick=function(){document.querySelectorAll('.interview-mode-toggle button').forEach(function(b){b.classList.remove('active')});btn.classList.add('active');var mode=btn.dataset.interviewMode==='adjust'?'adjust':'answer';if(input){input.placeholder=mode==='adjust'?'例如：请围绕第 4 页的数据来源追问…':'输入你的现场回答…'}var submit=el('interviewSubmitBtn');if(submit)submit.textContent=mode==='adjust'?'调整提问':'发送'}})}
async function uploadDefenseMaterials(){if(!ivChat.files.length)return{material_text:'',files:[]};var form=new FormData();ivChat.files.forEach(function(file){form.append('files',file)});var response=await fetch('/api/interview/materials',{method:'POST',body:form});var data=await response.json();if(!response.ok)throw Error(alertMessages(data.detail||data).join('；'));return data}
async function startInterviewChat(){var btn=el('startInterviewBtn');var script=el('defenseScript');var req=el('interviewRequirements');ivChat.script=script?script.value.trim():ivChat.script.trim();ivChat.requirements=req?req.value.trim():ivChat.requirements.trim();var hasPlan=state.plan&&state.plan.plan&&state.plan.plan.tasks&&state.plan.plan.tasks.length;if(!ivChat.script&&!ivChat.files.length&&!hasPlan){showNotice('请先粘贴答辩稿、上传材料，或先生成项目方案','info');return}btn.disabled=true;btn.innerHTML='<span class="spinner-inline"></span>解析材料…';try{var uploaded=await uploadDefenseMaterials();ivChat.materialText=[ivChat.script,uploaded.material_text||''].filter(Boolean).join('\n\n');ivChat.materialNames=(ivChat.script?['粘贴的答辩稿']:[]).concat((uploaded.files||[]).map(function(file){return file.name}));btn.innerHTML='<span class="spinner-inline"></span>生成问题…';var data=await jsonRequest('/api/interview',{plan:state.plan?state.plan.plan:null,qa_matrix:state.plan?state.plan.qa_matrix:null,user_requirements:ivChat.requirements,project_context:defenseRequirementText().slice(0,8000),material_text:ivChat.materialText,material_names:ivChat.materialNames});ivChat.started=true;ivChat.messages=[];var firstQ=(data.questions&&data.questions[0])||fallbackInterviewQuestion();var intro=ivChat.materialText?'我会只围绕你提交的答辩材料逐题提问并点评。':'我会围绕你的项目方案逐题提问并点评。';ivChat.messages.push({role:'assistant',content:'答辩模拟开始。'+intro+'\n\n'+firstQ});renderInterviewChat();el('interviewForm').classList.remove('hidden');el('interviewAnswer').disabled=false;document.querySelectorAll('.interview-mode-toggle button').forEach(function(b){b.classList.toggle('active',b.dataset.interviewMode==='answer')});el('interviewAnswer').placeholder='输入你的现场回答…';var submit=el('interviewSubmitBtn');if(submit)submit.textContent='发送'}catch(e){showNotice(e.message,'error')}finally{btn.disabled=false;btn.textContent='开始答辩模拟'}}

function fallbackInterviewQuestion(){var tasks=state.plan&&state.plan.plan&&state.plan.plan.tasks||[];if(tasks.length){return '请介绍「'+tasks[0].name+'」这项任务的核心思路、关键决策和交付内容。'}var course=state.plan&&state.plan.input&&state.plan.input.course;if(course&&course.name){return '请介绍「'+course.name+'」这个项目的核心目标、主要成果和你的个人贡献。'}return '请概括这个项目最核心的成果和你负责的部分。'}
function resetInterviewChat(){ivChat.started=false;ivChat.messages=[];var msgBox=el('interviewMessages');if(msgBox)msgBox.innerHTML='<div class="interview-placeholder">提交答辩稿或 PPT 后，AI 评委会围绕材料逐题提问。</div>';var form=el('interviewForm');if(form)form.classList.add('hidden')}
function renderInterviewChat(){var msgBox=el('interviewMessages');if(!msgBox)return;msgBox.innerHTML=ivChat.messages.map(function(msg,idx){var speak=msg.role==='assistant'?'<button type="button" class="msg-audio-btn" data-speak-idx="'+idx+'" aria-label="播报这条回复">🔊 播报</button>':'';return '<div class="'+(msg.role==='user'?'user-msg':'assistant-msg')+'">'+esc(msg.content)+speak+'</div>'}).join('');msgBox.scrollTop=msgBox.scrollHeight;msgBox.querySelectorAll('[data-speak-idx]').forEach(function(btn){btn.onclick=function(){speakInterviewText(ivChat.messages[+btn.dataset.speakIdx].content,btn)}})}

function ensureInterviewVoiceControls(){var form=el('interviewForm');if(!form||form.querySelector('.interview-voice-controls'))return;var submit=el('interviewSubmitBtn');var wrap=document.createElement('div');wrap.className='interview-voice-controls';wrap.innerHTML='<label class="voice-toggle" title="把 AI 回复用语音播报（需云端 MiniCPM-o）"><input type="checkbox" id="interviewVoiceToggle"><span>语音播报</span></label><button type="button" id="interviewMicBtn" class="mic-btn" aria-label="语音输入回答" title="语音输入回答">🎤</button><button type="button" id="interviewVideoBtn" class="mic-btn" aria-label="录像回答并分析表现" title="录像回答，AI 看表情并转写回答">📹</button>';if(submit){form.insertBefore(wrap,submit)}else{form.appendChild(wrap)}bindInterviewVoiceControls()}

function bindInterviewVoiceControls(){var toggle=el('interviewVoiceToggle'),mic=el('interviewMicBtn'),videoBtn=el('interviewVideoBtn');var rt=state.realtime||{};if(toggle){var ok=rt.enabled&&!state.realtimeFallback&&rt.backend==='map';toggle.disabled=!ok;toggle.checked=!!ivChat.voiceEnabled&&ok;if(!ok)ivChat.voiceEnabled=false;var label=toggle.closest('.voice-toggle');if(label)label.classList.toggle('disabled',!ok);toggle.onchange=function(){ivChat.voiceEnabled=this.checked}}if(mic)mic.onclick=function(){toggleRecording(sendInterviewVoice,'interview')};if(videoBtn)videoBtn.onclick=openVideoRecorder}

function interviewHistoryForJudge(){return (ivChat.messages||[]).map(function(m){return{role:m.role,content:String(m.content||'')}}).filter(function(m){return m.content})}function interviewJudgeContext(){var parts=[];parts.push('你是答辩模拟的评委。以下是本次模拟的背景：');parts.push('项目要求：'+(defenseRequirementText().slice(0,3000)||'未提供'));if(ivChat.materialText)parts.push('答辩材料：'+ivChat.materialText.slice(0,8000));if(ivChat.requirements)parts.push('评委关注点：'+ivChat.requirements);return parts.join('\n\n')}

function appendInterviewTurnUser(label){ivChat.messages.push({role:'user',content:label});renderInterviewChat()}

async function sendInterviewVoice(blob){var mic=el('interviewMicBtn');if(mic)mic.disabled=true;showNotice('评委正在听你的回答…','info');var hist=interviewHistoryForJudge();appendInterviewTurnUser('🎤 [语音回答]');try{var fd=new FormData();fd.append('file',blob,'voice.webm');fd.append('system_prompt',interviewJudgeContext());fd.append('history',JSON.stringify(hist));var r=await fetch('/api/realtime/interview-turn',{method:'POST',body:fd});var data=await r.json();if(!r.ok)throw Error(alertMessages(data.detail||data).join('；'));finishInterviewTurn(data,'语音')}catch(err){finishInterviewTurnError(err)}finally{if(mic)mic.disabled=false}}

function finishInterviewTurn(data,kind){var reply=typeof data.reply==='string'?data.reply:String(data.reply||'');var summary=(data.summary||'').trim();if(ivChat.messages.length&&ivChat.messages[ivChat.messages.length-1].role==='user'){ivChat.messages[ivChat.messages.length-1]=Object.assign({},ivChat.messages[ivChat.messages.length-1],{content:summary?('🎤 ['+kind+'回答] 要点：'+summary):('🎤 ['+kind+'回答]')})}ivChat.messages.push({role:'assistant',content:reply});renderInterviewChat();if(ivChat.voiceEnabled&&reply){speakInterviewText(reply,null)}showNotice('评委已回复','success')}

function finishInterviewTurnError(err){ivChat.messages.push({role:'assistant',content:'语音问答失败：'+err.message});renderInterviewChat();showNotice('语音问答失败：'+err.message,'error')}

async function sendInterviewVideo(blob){var videoBtn=el('interviewVideoBtn');if(videoBtn)videoBtn.disabled=true;showNotice('评委正在看你的回答视频…','info');var hist=interviewHistoryForJudge();appendInterviewTurnUser('🎥 [视频回答]');try{var fd=new FormData();fd.append('file',blob,'answer.webm');fd.append('system_prompt',interviewJudgeContext());fd.append('history',JSON.stringify(hist));var r=await fetch('/api/realtime/interview-turn',{method:'POST',body:fd});var data=await r.json();if(!r.ok)throw Error(alertMessages(data.detail||data).join('；'));finishInterviewTurn(data,'视频')}catch(err){finishInterviewTurnError(err)}finally{if(videoBtn)videoBtn.disabled=false}}

function showLinkModal(title,url){var modal=el('linkModal');if(!modal)return;modal.classList.remove('hidden');var t=el('linkModalTitle'),txt=el('linkModalText'),cp=el('linkModalCopy'),done=el('linkModalDone'),close=el('linkModalClose');if(t)t.textContent=title;if(txt){txt.value=url;txt.focus();txt.select();txt.setSelectionRange(0,url.length)}if(cp){cp.textContent='复制链接';cp.onclick=async function(){var ok=await copyText(url);if(ok){cp.textContent='已复制 ✓';showNotice('链接已复制','success')}else{showNotice('复制失败，请长按上方链接文字复制','info')}}}if(done)done.onclick=function(){modal.classList.add('hidden')};if(close)close.onclick=function(){modal.classList.add('hidden')};copyText(url).then(function(ok){if(ok&&cp)cp.textContent='已复制 ✓'})}function fallbackCopy(text){try{var ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.opacity='0';ta.style.left='-9999px';document.body.appendChild(ta);ta.focus();ta.select();ta.setSelectionRange(0,text.length);var ok=document.execCommand('copy');document.body.removeChild(ta);return ok}catch(e){return false}}function copyText(text){return new Promise(function(resolve){if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(text).then(function(){resolve(true)},function(){resolve(fallbackCopy(text))})}else{resolve(fallbackCopy(text))}})}async function generateReportLink(){if(!state.lastSavedFilename){showNotice('请先保存方案，再生成成员汇报链接','info');return}var members=((state.plan&&state.plan.input&&state.plan.input.members)||[]).filter(function(m){return m.name});var vols=((state.plan&&state.plan.volunteer_pool)||[]).filter(function(v){return v.status==='已确认'&&v.name&&!members.some(function(m){return m.name===v.name})}).map(function(v){return{name:v.name,role:'志愿者'}});members=members.concat(vols);if(!members.length){showNotice('方案中没有成员','info');return}var isLarge=state.plan&&state.plan.input&&state.plan.input.project_mode==='large_project';var labels=members.map(function(m){var role=m.role||'';var star=(isLarge&&role==='项目负责人')?' ★ 团队总览':'';return m.name+(role&&role!=='执行成员'?('（'+role+'）'):'')+star});var hint=isLarge?'\n提示：选择带「★ 团队总览」的项目负责人，可查看全项目进度。':'\n大型项目如无「项目负责人」，可在项目配置添加该角色成员后再生成。';var recommended=members[0].name;if(isLarge){var leader=members.filter(function(m){return m.role==='项目负责人'})[0];if(leader)recommended=leader.name}var member=prompt('为哪位成员生成汇报链接？\n成员：'+labels.join('\n')+hint,recommended);if(!member)return;var picked=member.replace(/（.*$/,'').replace(/★.*$/,'').trim();try{var data=await jsonRequest('/api/report/link',{filename:state.lastSavedFilename,member:picked});var url=location.origin+data.url;showLinkModal('汇报链接已生成',url)}catch(e){showNotice(e.message,'error')}}

function enterReportMode(token){state.reportToken=token;var nav=el('stepNav'),main=document.querySelector('.app-main'),assist=el('assistantBtn'),reportView=el('reportView');if(nav)nav.classList.add('hidden');if(main)main.classList.add('hidden');if(assist)assist.classList.add('hidden');if(reportView)reportView.classList.remove('hidden');loadReportState();document.addEventListener('visibilitychange',function(){if(document.visibilityState==='visible')loadReportState()});window.addEventListener('focus',function(){loadReportState()})}

async function loadReportState(){try{var r=await fetch('/api/report/state?token='+encodeURIComponent(state.reportToken));var data=await r.json();if(!r.ok)throw Error(alertMessages(data.detail||data).join('；'));var pj=el('reportProject'),mb=el('reportMember'),dl=el('reportDeadline');if(pj)pj.textContent=data.project;if(mb)mb.textContent='成员：'+data.member;if(dl)dl.textContent='截止：'+data.deadline;state.reportMember=data.member;state.reportOverview=data.overview||null;state.reportTasks=data.tasks||[];renderReportTasks()}catch(e){reportNotice(e.message,'error')}}

function reportNotice(msg,type){var n=el('reportNotice');if(!n){showNotice(msg,type);return}n.textContent=msg;n.className='notice '+(type||'info');n.classList.remove('hidden');clearTimeout(state.reportNoticeTimer);state.reportNoticeTimer=setTimeout(function(){n.classList.add('hidden')},4000)}

function reportStatusLabel(s){return{pending:'待开始',in_progress:'进行中',completed:'已完成',blocked:'阻塞',confirmed:'已完成'}[s]||s}

function renderReportOverview(){var o=state.reportOverview;if(!o)return'';var st=o.stats||{};var pct=st.total?Math.round(st.completed/st.total*100):0;var html='<div class="report-overview"><div class="report-overview-head"><div class="report-overview-title"><h3>团队总览</h3><p>'+esc(o.project)+' · 截止 '+esc(String(o.deadline||'').slice(0,10))+'</p></div><div class="report-overview-stats"><span><strong>'+st.completed+'/'+st.total+'</strong>任务完成</span><span><strong>'+(st.actual_hours!=null?st.actual_hours:0)+'h</strong>实际工时</span><span><strong>'+(st.planned_hours!=null?st.planned_hours:0)+'h</strong>计划工时</span></div></div><div class="report-overview-progress"><i style="width:'+pct+'%"></i></div>'+(o.modules||[]).map(function(md){var mp=md.task_count?Math.round(md.completed_count/md.task_count*100):0;return '<div class="report-module"><div class="report-module-head"><span class="module-code">'+esc(md.id)+'</span><div><strong>'+esc(md.name)+'</strong><span>骨干：'+esc(md.assignee_id||'未认领')+' · '+md.completed_count+'/'+md.task_count+' 完成</span></div></div><div class="report-module-progress"><i style="width:'+mp+'%"></i></div>'+(md.tasks||[]).map(function(t){var rows=(t.members||[]).map(function(mem){var cls=mem.status==='completed'?'report-member-ok':(mem.status==='blocked'?'report-member-bad':'report-member-info');var awaitB=mem.awaiting_confirm?'<span class="report-await-badge">待确认</span>':'';var photo=mem.photo?'<a class="report-photo-badge" href="/api/report/attachment?token='+encodeURIComponent(state.reportToken)+'&task_id='+encodeURIComponent(t.id)+'" target="_blank" rel="noopener" title="查看交付物">📷</a>':'';var hours=mem.actual_hours!=null?' · '+mem.actual_hours+'h':'';return '<div class="report-member-row"><i class="report-member-dot '+cls+'"></i><span class="report-member-name">'+esc(mem.name)+'</span><span class="report-member-role">'+esc(mem.role)+'</span><span class="report-member-status '+cls+'">'+esc(reportStatusLabel(mem.status)||'未开始')+'</span>'+awaitB+photo+'<span class="report-member-note">'+esc(mem.note)+'</span>'+hours+'</div>'}).join('');return '<div class="report-overview-task"><div class="report-overview-task-head"><strong>'+esc(t.id)+' '+esc(t.name)+'</strong><span class="report-status-chip">'+esc(reportStatusLabel(t.status))+'</span></div>'+(rows?'<div class="report-members">'+rows+'</div>':'')+'</div>'}).join('')+'</div>'}).join('')+'</div>';return html}function renderReportTasks(){var target=el('reportTasks');if(!target)return;var overviewHtml=renderReportOverview();if(!state.reportTasks.length){target.innerHTML=overviewHtml+'<div class="success-box">当前没有分配给你的任务</div>';return}target.innerHTML=overviewHtml+state.reportTasks.map(function(t){var isCollab=t.role==='协作者'||t.role==='志愿者';var myStatus=t.status;if(isCollab){var meRow=(t.members||[]).filter(function(m){return m.name===(state.reportMember||'')})[0];if(meRow&&meRow.status)myStatus=(meRow.status==='confirmed'?'completed':meRow.status)}var statusOpts=['pending','in_progress','completed','blocked'].map(function(s){return '<option value="'+s+'" '+(myStatus===s?'selected':'')+'>'+reportStatusLabel(s)+'</option>'}).join('');var notes=((t.notes||[]).map(function(n){return '<span>'+esc(n)+'</span>'}).join(''));var totalRow=t.actual_hours!=null?'<div class="report-members-total">累计工时：<strong>'+t.actual_hours+'h</strong>（各成员上报之和）</div>':'';var memberRows=(t.members||[]).map(function(m){var self=m.name===(state.reportMember||'');var statusCls=(m.status==='completed'||m.status==='confirmed')?'report-member-ok':(m.status==='blocked'?'report-member-bad':'report-member-info');var awaitBadge=m.awaiting_confirm?'<span class="report-await-badge">待负责人确认</span>':'';var actBtn='';if(t.role==='负责人'&&!self){if(m.status==='confirmed'){actBtn='<span class="report-owner-badge">已确认</span>'}else{actBtn='<button type="button" class="btn btn-small report-confirm-member" data-task="'+esc(t.id)+'" data-member="'+esc(m.name)+'" title="为对方补录完成状态">'+(m.awaiting_confirm?'确认完成':'标记完成')+'</button>'}}var photo=m.photo?((t.role==='负责人'||self)?'<a class="report-photo-badge" href="/api/report/attachment?token='+encodeURIComponent(state.reportToken)+'&task_id='+encodeURIComponent(t.id)+'" target="_blank" rel="noopener" title="查看交付物照片">📷 查看交付物</a>':'<span class="report-photo-badge">📷 已交付</span>'):'';var hours=((t.role==='负责人'||self)&&m.actual_hours!=null)?(' · '+m.actual_hours+'h'):'';return '<div class="report-member-row"><i class="report-member-dot '+statusCls+'"></i><span class="report-member-name">'+esc(m.name)+'</span><span class="report-member-role">'+esc(m.role)+'</span><span class="report-member-status '+statusCls+'">'+esc(reportStatusLabel(m.status)||'未开始')+'</span>'+awaitBadge+actBtn+photo+'<span class="report-member-note">'+esc(((self||t.role==='负责人')&&m.note)?m.note:'')+'</span>'+hours+'</div>'}).join('');var revertWarn='';if(t.role==='负责人'&&t.status==='in_progress'){var ownerRow=(t.members||[]).filter(function(m){return m.role==='负责人'})[0];if(ownerRow&&ownerRow.status==='completed'){revertWarn='<div class="report-revert-warning">⚠ 任务已回退为进行中（有成员改回未完成），请重新确认后再标记完成</div>'}}return '<div class="report-task-card" data-task="'+esc(t.id)+'"><div class="report-task-head"><strong>'+esc(t.id)+' '+esc(t.name)+'</strong><span class="report-role">'+esc(t.role)+'</span><span class="report-chip-label">任务状态</span><span class="report-status-chip">'+esc(reportStatusLabel(t.status))+'</span></div>'+revertWarn+'<div class="report-task-meta">计划 '+t.estimated_hours+'h'+(t.end_date?' · 截止 '+String(t.end_date).slice(0,10):'')+(t.actual_hours!=null?' · 实际 '+t.actual_hours+'h':'')+(t.actual_end_date?' · 完成 '+String(t.actual_end_date).slice(0,10):'')+(isCollab?' · 我的部分完成后由负责人确认':'')+'</div><div class="report-task-controls">'+(isCollab?'<span class="report-my-status">我的状态</span>':'')+'<select class="report-status" aria-label="状态" title="'+(isCollab?'我的状态（任务状态由负责人确认）':'切换后自动保存')+'">'+statusOpts+'</select><input class="report-hours" type="number" min="0" step="0.5" placeholder="我的工时" value="">'+(isCollab?'':'<input class="report-date" type="date" title="完成日期（负责人设置）" value="'+(t.actual_end_date?String(t.actual_end_date).slice(0,10):'')+'">')+'<button type="button" class="btn btn-ghost report-voice">🎤 语音汇报</button><button type="button" class="btn btn-ghost report-photo">📷 交付物</button><button type="button" class="btn btn-primary report-apply">应用</button></div>'+(memberRows.length?'<div class="report-members"><div class="report-members-title">成员进度</div>'+memberRows+totalRow+'</div>':'')+(notes?'<div class="report-notes">'+notes+'</div>':'')+'</div>'}).join('');bindReportControls()}

function bindReportControls(){document.querySelectorAll('.report-voice').forEach(function(btn){btn.onclick=function(){var card=btn.closest('.report-task-card');state.reportVoiceTask=card.dataset.task;state.reportPending=null;toggleRecording(reportVoiceDone,'report')}});document.querySelectorAll('.report-photo').forEach(function(btn){btn.onclick=function(){var card=btn.closest('.report-task-card');state.reportVoiceTask=card.dataset.task;state.reportPending=null;openCamera('report')}});document.querySelectorAll('.report-status').forEach(function(sel){sel.onchange=function(){var card=sel.closest('.report-task-card');if(!card)return;applyReportUpdate(card.dataset.task,collectReportCard(card),null)}});document.querySelectorAll('.report-confirm-member').forEach(function(btn){btn.onclick=function(){applyReportMemberConfirm(btn.dataset.task,btn.dataset.member)}});document.querySelectorAll('.report-apply').forEach(function(btn){btn.onclick=function(){var card=btn.closest('.report-task-card');applyReportUpdate(card.dataset.task,collectReportCard(card),null)}});var photoInput=el('reportPhotoInput');if(photoInput)photoInput.onchange=reportPhotoSelected}

