function bindAssistantDrag(){var btn=el('assistantBtn'),drag=null,suppressClick=false,raf=0;requestAnimationFrame(function(){var saved=null;try{saved=JSON.parse(localStorage.getItem('assistant_button_position')||'null')}catch(e){}if(saved&&Number.isFinite(saved.left)&&Number.isFinite(saved.top)){btn.style.left=saved.left+'px';btn.style.top=saved.top+'px';btn.style.right='auto';btn.style.bottom='auto'}clampAssistantButton()});btn.addEventListener('pointerdown',function(event){if(event.button!==undefined&&event.button!==0)return;var rect=btn.getBoundingClientRect();drag={pointerId:event.pointerId,startX:event.clientX,startY:event.clientY,left:rect.left,top:rect.top,moved:false,nextX:rect.left,nextY:rect.top};btn.setPointerCapture(event.pointerId)});btn.addEventListener('pointermove',function(event){if(!drag||drag.pointerId!==event.pointerId)return;var dx=event.clientX-drag.startX,dy=event.clientY-drag.startY;if(!drag.moved&&Math.hypot(dx,dy)<5)return;drag.moved=true;drag.nextX=clampNumber(drag.left+dx,12,window.innerWidth-btn.offsetWidth-12);drag.nextY=clampNumber(drag.top+dy,12,window.innerHeight-btn.offsetHeight-12);if(raf)return;raf=requestAnimationFrame(function(){raf=0;if(!drag)return;btn.classList.add('dragging');btn.style.left=Math.round(drag.nextX)+'px';btn.style.top=Math.round(drag.nextY)+'px';btn.style.right='auto';btn.style.bottom='auto';if(!el('assistantDrawer').classList.contains('hidden'))positionAssistantDrawer()})});function finishDrag(event){if(!drag||drag.pointerId!==event.pointerId)return;var moved=drag.moved;drag=null;if(raf){cancelAnimationFrame(raf);raf=0}btn.classList.remove('dragging');if(moved){suppressClick=true;var pos=clampAssistantButton();try{localStorage.setItem('assistant_button_position',JSON.stringify(pos))}catch(e){}if(!el('assistantDrawer').classList.contains('hidden'))positionAssistantDrawer()}}btn.addEventListener('pointerup',finishDrag);btn.addEventListener('pointercancel',finishDrag);btn.addEventListener('click',function(event){if(suppressClick){suppressClick=false;event.preventDefault();return}toggleAssistant()});window.addEventListener('resize',function(){clampAssistantButton();if(!el('assistantDrawer').classList.contains('hidden'))positionAssistantDrawer()});document.addEventListener('keydown',function(event){if(event.key==='Escape'&&!el('assistantDrawer').classList.contains('hidden'))closeAssistant()})}
