function enableAuthFetch(token){if(token)localStorage.setItem('app_admin_token',token);if(!authToken()&&!state.shareToken)return;if(window.__authFetchWrapped)return;window.__authFetchWrapped=true;var orig=window.fetch;window.fetch=function(url,options){options=options||{};var headers=new Headers(options.headers||{});var t=authToken();if(String(url).indexOf('/api/')>=0&&t)headers.set('Authorization','Bearer '+t);if(String(url).indexOf('/api/')>=0&&state.shareToken)headers.set('X-Share-Token',state.shareToken);options.headers=headers;return orig(url,options).then(function(resp){if(resp.status===401&&String(url).indexOf('/api/auth/login')<0&&String(url).indexOf('/api/share/')<0&&!state.shareToken){openAuthModal()}return resp})}}
